	"paytmcall/internal/auth"
)

func TestPhoneValidation(t *testing.T) {
	for num, want := range map[string]bool{
		"[redacted]":  true,
		"[redacted]":     false,
		"+91987654321":   false,
		"+9198765432100": false,
		"+14155550100":   false,
		"[redacted]a":  false,
	} {
		if got := phoneRe.MatchString(num); got != want {
			t.Errorf("%s: got %v want %v", num, got, want)
		}
	}
}

func TestTokenRoundTrip(t *testing.T) {
	t.Setenv("JWT_SECRET", strings.Repeat("k", 32))
	tok, err := auth.Issue("user-1")
	if err != nil {
		t.Fatal(err)
	}
	if uid, err := auth.Parse(tok); err != nil || uid != "user-1" {
		t.Fatalf("parse: %q %v", uid, err)
	}
	if _, err := auth.Parse(tok[:len(tok)-2] + "xx"); err == nil {
		t.Fatal("tampered token accepted")
	}
	t.Setenv("JWT_SECRET", strings.Repeat("z", 32))
	if _, err := auth.Parse(tok); err == nil {
		t.Fatal("token signed with other secret accepted")
	}
	t.Setenv("JWT_SECRET", "short")
	if _, err := auth.Issue("u"); err == nil {
		t.Fatal("short secret accepted")
	}
}

func TestProtectedRoutesRejectMissingToken(t *testing.T) {
	t.Setenv("JWT_SECRET", strings.Repeat("k", 32))
	h := New()
	for _, rt := range []string{"POST /api/dial", "GET /api/calls", "POST /api/calls/x", "GET /api/calls/x"} {
		method, path, _ := strings.Cut(rt, " ")
		for _, header := range []string{"", "Bearer garbage"} {
			req := httptest.NewRequest(method, path, strings.NewReader(`{}`))
			if header != "" {
				req.Header.Set("Authorization", header)
			}
			rec := httptest.NewRecorder()
			h.ServeHTTP(rec, req)
			if rec.Code != http.StatusUnauthorized {
				t.Errorf("%s with %q: got %d", rt, header, rec.Code)
			}
		}
	}
}
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/zalando/go-keyring"
)

// Override at build time: wails build -ldflags "-X main.apiURL=https://your-app.vercel.app"
var apiURL = "http://localhost:8080"

const (
	keyringService = "laptop-dialer"
	keyringUser    = "jwt"
)

// ErrSignedOut tells the UI to show the sign-in screen.
var ErrSignedOut = errors.New("signed out")

type App struct {
	ctx    context.Context
	client *http.Client
}

func NewApp() *App {
	return &App{client: &http.Client{Timeout: 15 * time.Second}}
}

func (a *App) startup(ctx context.Context) { a.ctx = ctx }

type Call struct {
	ID        string     `json:"id"`
	Mode      string     `json:"mode"`
	To        string     `json:"to"`
	Status    string     `json:"status"`
	DurationS int        `json:"duration_s"`
	CreatedAt time.Time  `json:"created_at"`
	EndedAt   *time.Time `json:"ended_at,omitempty"`
}

func (a *App) LoggedIn() bool {
	_, err := keyring.Get(keyringService, keyringUser)
	return err == nil
}

func (a *App) Login(email, password string) error  { return a.auth("/api/login", email, password) }
func (a *App) Signup(email, password string) error { return a.auth("/api/signup", email, password) }

func (a *App) Logout() error {
	if err := keyring.Delete(keyringService, keyringUser); err != nil && !errors.Is(err, keyring.ErrNotFound) {
		return err
	}
	return nil
}

func (a *App) auth(path, email, password string) error {
	var out struct {
		Token string `json:"token"`
	}
	if err := a.do(http.MethodPost, path, map[string]string{"email": email, "password": password}, &out, false); err != nil {
		return err
	}
	return keyring.Set(keyringService, keyringUser, out.Token)
}

// Dial asks the linked phone to call number; returns the call ID to poll.
func (a *App) Dial(number string) (string, error) {
	to, err := normalizeIndian(number)
	if err != nil {
		return "", err
	}
	var out struct {
		ID string `json:"id"`
	}
	err = a.do(http.MethodPost, "/api/dial", map[string]string{"to": to}, &out, true)
	return out.ID, err
}

func (a *App) GetCall(id string) (Call, error) {
	var c Call
	err := a.do(http.MethodGet, "/api/calls/"+id, nil, &c, true)
	return c, err
}

func (a *App) ListCalls() ([]Call, error) {
	var cs []Call
	err := a.do(http.MethodGet, "/api/calls", nil, &cs, true)
	return cs, err
}

func (a *App) do(method, path string, body, out any, authed bool) error {
	var buf bytes.Buffer
	if body != nil {
		json.NewEncoder(&buf).Encode(body)
	}
	req, err := http.NewRequestWithContext(a.ctx, method, apiURL+path, &buf)
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/json")
	if authed {
		tok, err := keyring.Get(keyringService, keyringUser)
		if err != nil {
			return ErrSignedOut
		}
		req.Header.Set("Authorization", "Bearer "+tok)
	}
	resp, err := a.client.Do(req)
	if err != nil {
		return fmt.Errorf("can't reach server: %w", err)
	}
	defer resp.Body.Close()
	if authed && resp.StatusCode == http.StatusUnauthorized {
		a.Logout()
		return ErrSignedOut
	}
	if resp.StatusCode >= 400 {
		var e struct {
			Error string `json:"error"`
		}
		if json.NewDecoder(resp.Body).Decode(&e) == nil && e.Error != "" {
			return errors.New(e.Error)
		}
		return fmt.Errorf("server error (%d)", resp.StatusCode)
	}
	if out == nil || resp.StatusCode == http.StatusNoContent {
		return nil
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

// normalizeIndian accepts "98765 43210", "098765-43210", "+91 98765 43210".
func normalizeIndian(s string) (string, error) {
	d := strings.Map(func(r rune) rune {
		if r >= '0' && r <= '9' {
			return r
		}
		return -1
	}, s)
	switch {
	case len(d) == 10:
	case len(d) == 11 && d[0] == '0':
		d = d[1:]
	case len(d) == 12 && strings.HasPrefix(d, "91"):
		d = d[2:]
	default:
		return "", errors.New("enter a 10-digit Indian number")
	}
	return "+91" + d, nil
}
