	}
}

func TestTokenRoundTrip(t *testing.T) {
	t.Setenv("JWT_SECRET", strings.Repeat("k", 32))
	tok, err := auth.Issue("user-1")
	if err != nil {
		t.Fatal(err)
	}
	if uid, err := auth.Parse(tok); err != nil || uid != "user-1" {
		t.Fatalf("parse: %q %v", uid, err)
	}
	if _, err := auth.Parse(tok[:len(tok)-2] + "xx"); err == nil {
		t.Fatal("tampered token accepted")
	}
	t.Setenv("JWT_SECRET", strings.Repeat("z", 32))
	if _, err := auth.Parse(tok); err == nil {
		t.Fatal("token signed with other secret accepted")
	}
	t.Setenv("JWT_SECRET", "short")
	if _, err := auth.Issue("u"); err == nil {
		t.Fatal("short secret accepted")
	}
}

