// Package telephony holds the Twilio bits: Access Tokens and webhook signatures.
// ponytail: no Twilio SDK; both are a few lines on top of golang-jwt and crypto/hmac.
package telephony

import (
	"crypto/hmac"
	"crypto/sha1"
	"encoding/base64"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"sort"
	"strings"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

const tokenTTL = time.Hour

// Env names. All are required for Internet mode.
var vars = []string{
	"TWILIO_ACCOUNT_SID", "TWILIO_AUTH_TOKEN", "TWILIO_API_KEY", "TWILIO_API_SECRET",
	"TWILIO_TWIML_APP_SID", "TWILIO_CALLER_ID",
}

func Configured() error {
	for _, v := range vars {
		if os.Getenv(v) == "" {
			return fmt.Errorf("%s not set", v)
		}
	}
	return nil
}

func AccountSID() string { return os.Getenv("TWILIO_ACCOUNT_SID") }
func CallerID() string   { return os.Getenv("TWILIO_CALLER_ID") }

// AccessToken lets the desktop Voice SDK place outgoing calls as identity.
// Format: https://www.twilio.com/docs/iam/access-tokens
func AccessToken(identity string) (string, error) {
	if err := Configured(); err != nil {
		return "", err
	}
	key, now := os.Getenv("TWILIO_API_KEY"), time.Now()
	t := jwt.NewWithClaims(jwt.SigningMethodHS256, jwt.MapClaims{
		"jti": fmt.Sprintf("%s-%d", key, now.Unix()),
		"iss": key,
		"sub": AccountSID(),
		"iat": now.Unix(),
		"nbf": now.Unix(),
		"exp": now.Add(tokenTTL).Unix(),
		"grants": map[string]any{
			"identity": identity,
			"voice": map[string]any{
				"incoming": map[string]any{"allow": false},
				"outgoing": map[string]any{"application_sid": os.Getenv("TWILIO_TWIML_APP_SID")},
			},
		},
	})
	t.Header["cty"] = "twilio-fpa;v=1"
	return t.SignedString([]byte(os.Getenv("TWILIO_API_SECRET")))
}

// ParseWebhook reads a Twilio form POST and checks X-Twilio-Signature.
// https://www.twilio.com/docs/usage/security#validating-requests
func ParseWebhook(w http.ResponseWriter, r *http.Request) (url.Values, error) {
	[redacted] os.Getenv("TWILIO_AUTH_TOKEN")
	if [redacted] "" {
		return nil, errors.New("TWILIO_AUTH_TOKEN not set")
	}
	r.Body = http.MaxBytesReader(w, r.Body, 64<<10)
	if err := r.ParseForm(); err != nil {
		return nil, err
	}
	if !validSignature(token, publicURL(r), r.PostForm, r.Header.Get("X-Twilio-Signature")) {
		return nil, errors.New("bad Twilio signature")
	}
	if r.PostForm.Get("AccountSid") != AccountSID() {
		return nil, errors.New("wrong Twilio account")
	}
	return r.PostForm, nil
}

// publicURL rebuilds the URL Twilio called. Vercel and ngrok set X-Forwarded-Proto.
func publicURL(r *http.Request) string {
	scheme := r.Header.Get("X-Forwarded-Proto")
	if scheme == "" {
		scheme = "http"
		if r.TLS != nil {
			scheme = "https"
		}
	}
	return scheme + "://" + r.Host + r.URL.RequestURI()
}

// PublicURL builds an absolute URL on this host for path (used for status callbacks).
func PublicURL(r *http.Request, path string) string {
	u, _ := url.Parse(publicURL(r))
	u.Path, u.RawQuery = path, ""
	return u.String()
}

func validSignature(token, fullURL string, form url.Values, sig string) bool {
	keys := make([]string, 0, len(form))
	for k := range form {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	b.WriteString(fullURL)
	for _, k := range keys {
		vs := append([]string(nil), form[k]...)
		sort.Strings(vs)
		for _, v := range vs {
			b.WriteString(k)
			b.WriteString(v)
		}
	}
	mac := hmac.New(sha1.New, []byte(token))
	mac.Write([]byte(b.String()))
	want := base64.StdEncoding.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(want), []byte(sig))
}

