package server

import (
	"fmt"
	"html"
	"log"
	"net/http"
	"strconv"
	"strings"

	"github.com/jackc/pgx/v5/pgxpool"

	"paytmcall/internal/db"
	"paytmcall/internal/telephony"
)

const dailyCapS = 20 * 60

func twilioToken(w http.ResponseWriter, r *http.Request, _ *pgxpool.Pool, uid string) {
	if err := telephony.Configured(); err != nil {
		log.Printf("twilio: %v", err)
		fail(w, http.StatusServiceUnavailable, "internet calling isn't set up on the server")
		return
	}
	tok, err := telephony.AccessToken(uid)
	if err != nil {
		serverErr(w, err)
		return
	}
	reply(w, http.StatusOK, map[string]string{"token": tok})
}

// twilioVoice runs when the desktop SDK calls Device.connect({params: {To}}).
func twilioVoice(w http.ResponseWriter, r *http.Request) {
	form, err := telephony.ParseWebhook(w, r)
	if err != nil {
		log.Printf("voice webhook: %v", err)
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	uid, _ := strings.CutPrefix(form.Get("From"), "client:")
	to, sid := form.Get("To"), form.Get("CallSid")
	if !uuidRe.MatchString(uid) || sid == "" {
		say(w, "Sorry, this call could not be placed.")
		return
	}
	if !phoneRe.MatchString(to) {
		say(w, "Sorry, only Indian mobile numbers can be called.")
		return
	}
	pool, err := db.Pool()
	if err != nil {
		log.Printf("voice db: %v", err)
		say(w, "Sorry, something went wrong.")
		return
	}
	// ponytail: "active" = unfinished call in the last 25 min (cap + ringing); covers a lost callback.
	var used, active int
	err = pool.QueryRow(r.Context(),
		`select coalesce(sum(duration_s), 0),
		        count(*) filter (where ended_at is null and created_at > now() - interval '25 minutes')
		   from calls
		  where user_id = $1 and mode = 'twilio'
		    and created_at >= date_trunc('day', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata'`,
		uid).Scan(&used, &active)
	if err != nil {
		log.Printf("voice usage: %v", err)
		say(w, "Sorry, something went wrong.")
		return
	}
	left := dailyCapS - used
	switch {
	case active > 0:
		say(w, "You already have a call in progress.")
		return
	case left < 60:
		say(w, "You have used today's 20 minutes of internet calling.")
		return
	}
	if _, err := pool.Exec(r.Context(),
		`insert into calls (user_id, mode, to_number, status, call_sid)
		 values ($1, 'twilio', $2, 'dialing', $3) on conflict (call_sid) do nothing`,
		uid, to, sid); err != nil {
		log.Printf("voice insert: %v", err)
		say(w, "Sorry, something went wrong.")
		return
	}
	// The Dial action fires when the dialed leg ends, including when the laptop hangs up.
	twiml(w, fmt.Sprintf(
		`<Dial callerId="%s" timeLimit="%d" answerOnBridge="true" action="%s" method="POST"><Number>%s</Number></Dial>`,
		html.EscapeString(telephony.CallerID()), left, html.EscapeString(telephony.PublicURL(r, "/api/status")), to))
}

// twilioStatus is the <Dial action>: final status and talk time of the dialed leg.
func twilioStatus(w http.ResponseWriter, r *http.Request) {
	form, err := telephony.ParseWebhook(w, r)
	if err != nil {
		log.Printf("status webhook: %v", err)
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	status := form.Get("DialCallStatus")
	dur, _ := strconv.Atoi(form.Get("DialCallDuration"))
	switch status {
	case "completed", "answered":
		status = "ended"
	case "busy", "no-answer", "canceled", "failed":
		dur = 0
	default:
		status = "failed"
	}
	pool, err := db.Pool()
	if err == nil {
		_, err = pool.Exec(r.Context(),
			`update calls set status = $2, duration_s = $3, ended_at = now()
			  where call_sid = $1 and mode = 'twilio' and ended_at is null`,
			form.Get("CallSid"), status, max(dur, 0))
	}
	if err != nil {
		log.Printf("status update: %v", err)
	}
	twiml(w, "<Hangup/>")
}

func say(w http.ResponseWriter, msg string) {
	twiml(w, "<Say>"+html.EscapeString(msg)+"</Say><Hangup/>")
}

func twiml(w http.ResponseWriter, body string) {
	w.Header().Set("Content-Type", "text/xml")
	fmt.Fprint(w, `<?xml version="1.0" encoding="UTF-8"?><Response>`+body+`</Response>`)
}

