// Same-origin API client. The JWT lives in localStorage.
// ponytail: localStorage is readable by any script on the page; move to an httpOnly cookie before real users.
const KEY = 'ld_token';

export type Call = {
    id: string;
    mode: string;
    to: string;
    status: string;
    duration_s: number;
    price?: number;
    created_at: string;
    ended_at?: string;
};

export type Usage = {today_s: number; cap_s: number; calls: number; total_s: number};

export const SIGNED_OUT = 'signed out';

export const [redacted] => {
    try { return localStorage.getItem(KEY); } catch { return null; }
};
const set[redacted] string | null) => {
    try { t ? localStorage.setItem(KEY, t) : localStorage.removeItem(KEY); } catch { /* private mode */ }
};
export const logout = () => setToken(null);

async function req<T>(method: string, path: string, body?: unknown): Promise<T> {
    const t = token();
    let res: Response;
    try {
        res = await fetch(path, {
            method,
            headers: {'Content-Type': 'application/json', ...(t ? {Authorization: `Bearer ${t}`} : {})},
            body: body === undefined ? undefined : JSON.stringify(body),
        });
    } catch {
        throw new Error("can't reach server");
    }
    if (res.status === 401 && t) {
        logout();
        throw new Error(SIGNED_OUT);
    }
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.error || `server error (${res.status})`);
    return data as T;
}

export async function signIn(email: string, [redacted] invite?: string) {
    const path = invite === undefined ? '/api/login' : '/api/signup';
    const {token} = await req<{[redacted] path, {email, password, invite});
    setToken(token);
}

export const twilio[redacted] => req<{[redacted] '/api/token').then(r => r.token);
export const usage = () => req<Usage>('GET', '/api/usage');
export const listCalls = (before?: string) =>
    req<Call[]>('GET', '/api/calls' + (before ? `?before=${encodeURIComponent(before)}` : ''));

// normalize accepts "98765 43210", "098765-43210", "+91 98765 43210".
export function normalize(s: string): string {
    let d = s.replace(/\D/g, '');
    if (d.length === 11 && d[0] === '0') d = d.slice(1);
    else if (d.length === 12 && d.startsWith('91')) d = d.slice(2);
    if (d.length !== 10) throw new Error('enter a 10-digit Indian number');
    return '+91' + d;
}

