import {FormEvent, useEffect, useMemo, useRef, useState} from 'react';
import {Call as TwilioCall, Device} from '@twilio/voice-sdk';
import {Call, listCalls, logout, normalize, SIGNED_OUT, signIn, token, twilioToken, usage, Usage} from './api';

type Phase = 'idle' | 'connecting' | 'ringing' | 'live';
type Tab = 'dial' | 'calls';

// Twilio errors carry code/description/explanation; plain errors carry message.
const errMsg = (e: any): string => {
    if (typeof e === 'string') return e;
    const text = e?.message || e?.explanation || e?.description || String(e);
    return e?.code ? `${text} (Twilio ${e.code})` : text;
};
const fmtDuration = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
const fmtTime = (t: string) => new Date(t).toLocaleString('en-IN', {dateStyle: 'medium', timeStyle: 'short'});

const statusLabel: Record<string, string> = {
    'no-answer': 'No answer', busy: 'Busy', canceled: 'Cancelled', failed: 'Failed', dialing: 'In progress',
};
const callLabel = (c: Call) =>
    c.status === 'ended' ? (c.duration_s > 0 ? 'Answered' : 'No answer') : statusLabel[c.status] ?? c.status;

export default function App() {
    const [signedIn, setSignedIn] = useState(!!token());
    return signedIn
        ? <Shell onSignedOut={() => { logout(); setSignedIn(false); }}/>
        : <SignIn onSignedIn={() => setSignedIn(true)}/>;
}

function SignIn({onSignedIn}: {onSignedIn: () => void}) {
    const [create, setCreate] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [invite, setInvite] = useState('');
    const [error, setError] = useState('');
    const [busy, setBusy] = useState(false);

    async function submit(e: FormEvent) {
        e.preventDefault();
        setBusy(true);
        setError('');
        try {
            await signIn(email, password, create ? invite : undefined);
            onSignedIn();
        } catch (err) {
            setError(errMsg(err));
        } finally {
            setBusy(false);
        }
    }

    return (
        <main>
            <h1>Laptop Dialer</h1>
            <p className="muted">Call Indian numbers from your browser using your mic and speakers.</p>
            <form onSubmit={submit}>
                <label>Email
                    <input type="email" required autoComplete="username" value={email}
                           onChange={e => setEmail(e.target.value)}/>
                </label>
                <label>Password
                    <input type="password" required minLength={8} maxLength={72}
                           autoComplete={create ? 'new-password' : 'current-password'}
                           value={password} onChange={e => setPassword(e.target.value)}/>
                </label>
                {create && (
                    <label>Invite code
                        <input required autoComplete="off" value={invite} onChange={e => setInvite(e.target.value)}/>
                    </label>
                )}
                {error && <p className="error" role="alert">{error}</p>}
                <button className="primary" disabled={busy}>{create ? 'Create account' : 'Sign in'}</button>
                <button type="button" className="link" disabled={busy} onClick={() => { setCreate(!create); setError(''); }}>
                    {create ? 'I already have an account' : 'Have an invite? Create account'}
                </button>
            </form>
        </main>
    );
}

function Shell({onSignedOut}: {onSignedOut: () => void}) {
    const [tab, setTab] = useState<Tab>('dial');
    const [number, setNumber] = useState('');
    const [use, setUse] = useState<Usage | null>(null);
    const [busy, setBusy] = useState(false);
    const [version, setVersion] = useState(0); // bump to reload records after a call

    const handle = (e: unknown, setError: (m: string) => void) => {
        const m = errMsg(e);
        if (m === SIGNED_OUT) onSignedOut();
        else setError(m);
    };
    useEffect(() => { usage().then(setUse).catch(e => handle(e, () => {})); }, [version]);

    return (
        <main className="wide">
            <header>
                <h1>Laptop Dialer</h1>
                <button className="link" disabled={busy} onClick={onSignedOut}>Sign out</button>
            </header>
            {use && (
                <p className="muted usage">
                    Today: {fmtDuration(use.today_s)} of {fmtDuration(use.cap_s)} used
                    <meter min={0} max={use.cap_s} value={use.today_s}/>
                </p>
            )}
            <nav className="tabs" role="tablist">
