    );
}

function Shell({onSignedOut}: {onSignedOut: () => void}) {
    const [tab, setTab] = useState<Tab>('dial');
    const [number, setNumber] = useState('');
    const [use, setUse] = useState<Usage | null>(null);
    const [busy, setBusy] = useState(false);
    const [version, setVersion] = useState(0); // bump to reload records after a call

    const handle = (e: unknown, setError: (m: string) => void) => {
        const m = errMsg(e);
        if (m === SIGNED_OUT) onSignedOut();
        else setError(m);
    };
    useEffect(() => { usage().then(setUse).catch(e => handle(e, () => {})); }, [version]);

    return (
        <main className="wide">
            <header>
                <h1>Laptop Dialer</h1>
                <button className="link" disabled={busy} onClick={onSignedOut}>Sign out</button>
            </header>
            {use && (
                <p className="muted usage">
                    Today: {fmtDuration(use.today_s)} of {fmtDuration(use.cap_s)} used
                    <meter min={0} max={use.cap_s} value={use.today_s}/>
                </p>
            )}
            <nav className="tabs" role="tablist">
                {(['dial', 'calls'] as const).map(t => (
                    <button key={t} role="tab" aria-selected={tab === t} disabled={busy && t !== tab} onClick={() => setTab(t)}>
                        {t === 'dial' ? 'Dialer' : 'Call records'}
                    </button>
                ))}
            </nav>
            {tab === 'dial'
                ? <Dialer number={number} setNumber={setNumber} setBusy={setBusy} onEnded={() => setVersion(v => v + 1)} handle={handle}/>
                : <Records version={version} use={use} handle={handle} onRedial={n => { setNumber(n); setTab('dial'); }}/>}
        </main>
    );
}

type Handle = (e: unknown, setError: (m: string) => void) => void;

function Dialer({number, setNumber, setBusy, onEnded, handle}: {
    number: string; setNumber: (n: string) => void; setBusy: (b: boolean) => void; onEnded: () => void; handle: Handle;
}) {
    const [phase, setPhase] = useState<Phase>('idle');
    const [calling, setCalling] = useState('');
    const [startedAt, setStartedAt] = useState(0);
    const [muted, setMuted] = useState(false);
    const [, tick] = useState(0);
    const [error, setError] = useState('');
    const device = useRef<Device | null>(null);
    const live = useRef<TwilioCall | null>(null);

    useEffect(() => () => device.current?.destroy(), []);
    useEffect(() => setBusy(phase !== 'idle'), [phase]);
    useEffect(() => {
        if (phase !== 'live') return;
        const t = setInterval(() => tick(n => n + 1), 1000);
        return () => clearInterval(t);
    }, [phase]);

    async function getDevice() {
        if (device.current) return device.current;
        const d = new Device(await twilioToken(), {codecPreferences: [TwilioCall.Codec.Opus, TwilioCall.Codec.PCMU]});
        d.on('tokenWillExpire', () => twilioToken().then(t => d.updateToken(t)).catch(e => handle(e, setError)));
        d.on('error', e => { console.error(e); setError(errMsg(e)); });
        return (device.current = d);
    }

    function ended() {
        live.current = null;
        setPhase('idle');
        setMuted(false);
        setTimeout(onEnded, 1500); // Twilio's status webhook lands a moment after hangup
    }

    async function call(e: FormEvent) {
        e.preventDefault();
        setError('');
        try {
            const to = normalize(number);
            setCalling(to);
            setPhase('connecting');
            const c = await (await getDevice()).connect({params: {To: to}});
            live.current = c;
            c.on('ringing', () => setPhase('ringing'));
            c.on('accept', () => { setStartedAt(Date.now()); setPhase('live'); });
            c.on('error', err => { console.error(err); setError(errMsg(err)); });
            for (const ev of ['disconnect', 'cancel', 'reject'] as const) c.on(ev, ended);
        } catch (err) {
            setPhase('idle');
            if (err !== undefined) handle(err, setError); // SDK rejects with nothing; the Device 'error' event already set the message
        }
    }

    function toggleMute() {
        live.current?.mute(!muted);
        setMuted(!muted);
    }

    const busy = phase !== 'idle';
    const statusText = {
        idle: '',
        connecting: 'Connecting…',
        ringing: 'Ringing…',
        live: fmtDuration(Math.floor((Date.now() - startedAt) / 1000)),
    }[phase];

    return (
        <>
            <form onSubmit={call} className="dialer">
                <label>Phone number
                    <div className="number">
                        <span>+91</span>
                        <input type="tel" inputMode="tel" required autoFocus placeholder="[redacted]"
                               value={number} onChange={e => setNumber(e.target.value)} disabled={busy}/>
                    </div>
                </label>
                {!busy && <button className="primary call">Call</button>}
                {error && <p className="error" role="alert">{error}</p>}
            </form>

            {busy && (
                <section className="status live" aria-live="polite">
                    <strong>{calling}</strong>
                    <span>{statusText}</span>
                    {phase === 'live' && (
                        <div className="keypad" aria-label="Keypad">
                            {'123456789*0#'.split('').map(k => (
                                <button key={k} onClick={() => live.current?.sendDigits(k)}>{k}</button>
                            ))}
                        </div>
                    )}
                    <div className="controls">
                        <button onClick={toggleMute} disabled={phase !== 'live'} aria-pressed={muted}>
                            {muted ? 'Unmute' : 'Mute'}
                        </button>
                        <button className="hangup" onClick={() => live.current ? live.current.disconnect() : ended()}>
                            Hang up
                        </button>
                    </div>
                </section>
            )}
        </>
    );
}

function Records({version, use, handle, onRedial}: {
    version: number; use: Usage | null; handle: Handle; onRedial: (n: string) => void;
}) {
    const [calls, setCalls] = useState<Call[]>([]);
    const [more, setMore] = useState(false);
    const [loading, setLoading] = useState(false);
    const [query, setQuery] = useState('');
    const [status, setStatus] = useState('all');
    const [error, setError] = useState('');

    async function load(before?: string) {
        setLoading(true);
        try {
            const page = await listCalls(before);
            setCalls(prev => (before ? [...prev, ...page] : page));
            setMore(page.length === 50);
        } catch (e) {
            handle(e, setError);
        } finally {
            setLoading(false);
        }
    }
    useEffect(() => { load(); }, [version]);

    const shown = useMemo(() => {
        const q = query.replace(/\D/g, '');
        return calls.filter(c => (!q || c.to.includes(q)) && (status === 'all' || callLabel(c) === status));
    }, [calls, query, status]);

    function exportCsv() {
        const rows = [['Date', 'Number', 'Status', 'Duration (s)'],
            ...shown.map(c => [c.created_at, c.to, callLabel(c), String(c.duration_s)])];
        const blob = new Blob([rows.map(r => r.join(',')).join('\n')], {type: 'text/csv'});
        const a = Object.assign(document.createElement('a'), {href: URL.createObjectURL(blob), download: 'calls.csv'});
        a.click();
        URL.revokeObjectURL(a.href);
    }

    const answered = calls.filter(c => c.duration_s > 0).length;
    return (
        <section>
            {use && (
                <div className="stats">
                    <div><strong>{use.calls}</strong><span>calls</span></div>
                    <div><strong>{fmtDuration(use.total_s)}</strong><span>talk time</span></div>
                    <div><strong>{calls.length ? Math.round((100 * answered) / calls.length) : 0}%</strong><span>answered</span></div>
                </div>
            )}
            <div className="filters">
                <input type="search" placeholder="Search number" value={query} onChange={e => setQuery(e.target.value)}
                       aria-label="Search number"/>
                <select value={status} onChange={e => setStatus(e.target.value)} aria-label="Status">
                    {['all', 'Answered', 'No answer', 'Busy', 'Cancelled', 'Failed', 'In progress'].map(s => (
                        <option key={s} value={s}>{s === 'all' ? 'All statuses' : s}</option>
                    ))}
                </select>
                <button onClick={exportCsv} disabled={!shown.length}>Export CSV</button>
            </div>
            {error && <p className="error" role="alert">{error}</p>}
            {!loading && shown.length === 0 && <p className="muted">No calls{calls.length ? ' match' : ' yet'}.</p>}
            {shown.length > 0 && (
                <table className="records">
                    <thead><tr><th>When</th><th>Number</th><th>Status</th><th>Duration</th><th/></tr></thead>
                    <tbody>
                    {shown.map(c => (
                        <tr key={c.id}>
                            <td>{fmtTime(c.created_at)}</td>
                            <td>{c.to}</td>
                            <td><span className={`badge ${c.duration_s > 0 ? 'ok' : ''}`}>{callLabel(c)}</span></td>
                            <td>{c.duration_s > 0 ? fmtDuration(c.duration_s) : '—'}</td>
                            <td><button className="link" onClick={() => onRedial(c.to.replace(/^\+91/, ''))}>Call</button></td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            )}
            {more && (
                <button className="more" disabled={loading} onClick={() => load(calls[calls.length - 1].created_at)}>
                    {loading ? 'Loading…' : 'Load more'}
                </button>
            )}
        </section>
    );
}

