import {FormEvent, useEffect, useRef, useState} from 'react';
import {Call as TwilioCall, Device} from '@twilio/voice-sdk';
import {ListCalls, LoggedIn, Login, Logout, Normalize, Signup, TwilioToken} from '../wailsjs/go/main/App';
import {main} from '../wailsjs/go/models';

type Call = main.Call;
type Phase = 'idle' | 'connecting' | 'ringing' | 'live';

// Twilio errors carry code/description/explanation; plain errors carry message.
const errMsg = (e: any): string => {
    if (typeof e === 'string') return e;
    const text = e?.message || e?.explanation || e?.description || String(e);
    return e?.code ? `${text} (Twilio ${e.code})` : text;
};
const fmtDuration = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
const fmtTime = (t: string) => new Date(t).toLocaleString('en-IN', {dateStyle: 'medium', timeStyle: 'short'});

const statusLabel: Record<string, string> = {
    'no-answer': 'No answer', busy: 'Busy', canceled: 'Cancelled', failed: 'Failed', dialing: 'In progress',
};
const historyLabel = (c: Call) =>
    c.status === 'ended' ? (c.duration_s > 0 ? fmtDuration(c.duration_s) : 'No answer') : statusLabel[c.status] ?? c.status;

export default function App() {
    const [loggedIn, setLoggedIn] = useState<boolean | null>(null);
    useEffect(() => { LoggedIn().then(setLoggedIn); }, []);
    if (loggedIn === null) return null;
    return loggedIn
        ? <Dialer onSignedOut={() => setLoggedIn(false)}/>
        : <SignIn onSignedIn={() => setLoggedIn(true)}/>;
}

function SignIn({onSignedIn}: {onSignedIn: () => void}) {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [busy, setBusy] = useState(false);

    async function submit(e: FormEvent, create: boolean) {
        e.preventDefault();
        setBusy(true);
        setError('');
        try {
            await (create ? Signup : Login)(email, password);
            onSignedIn();
        } catch (err) {
            setError(errMsg(err));
        } finally {
            setBusy(false);
        }
    }

    return (
        <main>
            <h1>Laptop Dialer</h1>
            <p className="muted">Calls go over the internet. Talk using your laptop mic and speakers.</p>
            <form onSubmit={e => submit(e, false)}>
                <label>Email
                    <input type="email" required autoComplete="username" value={email}
                           onChange={e => setEmail(e.target.value)}/>
                </label>
                <label>Password
                    <input type="password" required minLength={8} maxLength={72} autoComplete="current-password"
                           value={password} onChange={e => setPassword(e.target.value)}/>
                </label>
                {error && <p className="error" role="alert">{error}</p>}
                <button className="primary" disabled={busy}>Sign in</button>
                <button type="button" className="link" disabled={busy} onClick={e => submit(e, true)}>
                    Create account
                </button>
            </form>
        </main>
    );
}

function Dialer({onSignedOut}: {onSignedOut: () => void}) {
    const [number, setNumber] = useState('');
    const [phase, setPhase] = useState<Phase>('idle');
    const [calling, setCalling] = useState('');
    const [startedAt, setStartedAt] = useState(0);
    const [muted, setMuted] = useState(false);
    const [, tick] = useState(0);
    const [error, setError] = useState('');
    const [history, setHistory] = useState<Call[]>([]);
    const device = useRef<Device | null>(null);
    const live = useRef<TwilioCall | null>(null);

    const handle = (e: unknown) => {
        const m = errMsg(e);
        if (m === 'signed out') onSignedOut();
        else setError(m);
    };
    const refresh = () => ListCalls().then(cs => setHistory(cs ?? [])).catch(handle);
    useEffect(() => {
        refresh();
        return () => device.current?.destroy();
    }, []);
    useEffect(() => {
        if (phase !== 'live') return;
        const t = setInterval(() => tick(n => n + 1), 1000);
        return () => clearInterval(t);
    }, [phase]);

    async function getDevice() {
        if (device.current) return device.current;
        const d = new Device(await TwilioToken(), {codecPreferences: [TwilioCall.Codec.Opus, TwilioCall.Codec.PCMU]});
        d.on('tokenWillExpire', () => TwilioToken().then(t => d.updateToken(t)).catch(handle));
        d.on('error', e => { console.error(e); setError(errMsg(e)); });
        return (device.current = d);
    }

    function ended() {
        live.current = null;
        setPhase('idle');
        setMuted(false);
        setTimeout(refresh, 1500); // Twilio's status webhook lands a moment after hangup
    }

    async function call(e: FormEvent) {
        e.preventDefault();
        setError('');
        try {
            const to = await Normalize(number);
            setCalling(to);
            setPhase('connecting');
            const dev = await getDevice();
            const c = await dev.connect({params: {To: to}});
            live.current = c;
            c.on('ringing', () => setPhase('ringing'));
            c.on('accept', () => { setStartedAt(Date.now()); setPhase('live'); });
            c.on('error', err => { console.error(err); setError(errMsg(err)); });
            for (const ev of ['disconnect', 'cancel', 'reject'] as const) c.on(ev, ended);
        } catch (err) {
            setPhase('idle');
            if (err !== undefined) handle(err); // SDK rejects with nothing; the Device 'error' event already set the message
        }
    }

    function toggleMute() {
        live.current?.mute(!muted);
        setMuted(!muted);
    }

    const busy = phase !== 'idle';
    const statusText = {
        idle: '',
        connecting: 'Connecting…',
        ringing: 'Ringing…',
        live: fmtDuration(Math.floor((Date.now() - startedAt) / 1000)),
    }[phase];

    return (
        <main>
            <header>
                <h1>Laptop Dialer</h1>
                <button className="link" disabled={busy} onClick={() => Logout().then(onSignedOut)}>Sign out</button>
            </header>

            <form onSubmit={call} className="dialer">
                <label>Phone number
                    <div className="number">
                        <span>+91</span>
                        <input type="tel" inputMode="tel" required autoFocus placeholder="[redacted]"
                               value={number} onChange={e => setNumber(e.target.value)} disabled={busy}/>
                    </div>
                </label>
                {!busy && <button className="primary call">Call</button>}
                {error && <p className="error" role="alert">{error}</p>}
            </form>

            {busy && (
                <section className="status live" aria-live="polite">
                    <strong>{calling}</strong>
                    <span>{statusText}</span>
                    <div className="controls">
                        <button onClick={toggleMute} disabled={phase !== 'live'} aria-pressed={muted}>
                            {muted ? 'Unmute' : 'Mute'}
                        </button>
                        <button className="hangup" onClick={() => live.current ? live.current.disconnect() : ended()}>
                            Hang up
                        </button>
                    </div>
                </section>
            )}

            <h2>Recent calls</h2>
            {history.length === 0 && <p className="muted">No calls yet.</p>}
            <ul className="history">
                {history.map(c => (
                    <li key={c.id}>
                        <button className="row" onClick={() => setNumber(c.to.replace(/^\+91/, ''))} disabled={busy}>
                            <span>{c.to}<small>{fmtTime(c.created_at)}</small></span>
                            <span className="muted">{historyLabel(c)}</span>
                        </button>
                    </li>
                ))}
            </ul>
        </main>
    );
}

