package server

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net/http"
	"regexp"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"paytmcall/pkg/ai"
)

var (
	sidRe = regexp.MustCompile(`^CA[0-9a-f]{32}$`)
	ist   = time.FixedZone("IST", 5*3600+1800)
)

type call struct {
	ID           string     `json:"id"`
	Mode         string     `json:"mode"`
	To           string     `json:"to"`
	Status       string     `json:"status"`
	DurationS    int        `json:"duration_s"`
	Price        *float64   `json:"price,omitempty"`
	CreatedAt    time.Time  `json:"created_at"`
	EndedAt      *time.Time `json:"ended_at,omitempty"`
	Questions    string     `json:"questions"`
	Notes        string     `json:"notes"`
	Summary      string     `json:"summary"`
	CallbackAt   *time.Time `json:"callback_at"`
	CallbackDone bool       `json:"callback_done"`
	contact
}

type contact struct {
	Name       string `json:"name"`
	Business   string `json:"business"`
	CustomerID string `json:"customer_id"`
}

// Contact fields come from the number's current contact row, so edits show on every call to it.
const (
	callCols = `c.id, c.mode, c.to_number, c.status, c.duration_s, c.price, c.created_at, c.ended_at,
		c.questions, c.notes, c.summary, c.callback_at, c.callback_done,
		coalesce(ct.name, ''), coalesce(ct.business, ''), coalesce(ct.customer_id, '')`
	callFrom = ` from calls c left join contacts ct on ct.user_id = c.user_id and ct.phone = c.to_number `
)

func scanCall(row pgx.Row) (call, error) {
	var c call
	err := row.Scan(&c.ID, &c.Mode, &c.To, &c.Status, &c.DurationS, &c.Price, &c.CreatedAt, &c.EndedAt,
		&c.Questions, &c.Notes, &c.Summary, &c.CallbackAt, &c.CallbackDone,
		&c.Name, &c.Business, &c.CustomerID)
	return c, err
}

func queryCalls(ctx context.Context, pool *pgxpool.Pool, where string, args ...any) ([]call, error) {
	rows, err := pool.Query(ctx, `select `+callCols+callFrom+where, args...)
	if err != nil {
		return nil, err
	}
	return pgx.CollectRows(rows, func(r pgx.CollectableRow) (call, error) { return scanCall(r) })
}

// listCalls pages newest-first; pass ?before=<created_at of last row> for the next page.
func listCalls(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	before := time.Now().Add(time.Hour)
	if b := r.URL.Query().Get("before"); b != "" {
		t, err := time.Parse(time.RFC3339Nano, b)
		if err != nil {
			fail(w, http.StatusBadRequest, "invalid before")
			return
		}
		before = t
	}
	calls, err := queryCalls(r.Context(), pool,
		`where c.user_id = $1 and c.created_at < $2 order by c.created_at desc limit 50`, uid, before)
	if err != nil {
		serverErr(w, err)
		return
	}
	reply(w, http.StatusOK, calls)
}

func getCall(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	c, ok := loadCall(w, r, pool, uid, r.PathValue("id"))
	if ok {
		reply(w, http.StatusOK, c)
	}
}

// loadCall finds the user's call by id or Twilio CallSid, writing 404 if missing.
func loadCall(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid, ref string) (call, bool) {
	col := "c.id"
	switch {
	case sidRe.MatchString(ref):
		col = "c.call_sid"
	case !uuidRe.MatchString(ref):
		fail(w, http.StatusNotFound, "not found")
		return call{}, false
	}
	c, err := scanCall(pool.QueryRow(r.Context(),
		`select `+callCols+callFrom+`where `+col+` = $1 and c.user_id = $2`, ref, uid))
	if errors.Is(err, pgx.ErrNoRows) {
		fail(w, http.StatusNotFound, "not found")
		return call{}, false
	}
	if err != nil {
		serverErr(w, err)
		return call{}, false
	}
	return c, true
}

func getContact(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	phone := r.PathValue("phone")
	if !phoneRe.MatchString(phone) {
		fail(w, http.StatusBadRequest, "invalid number")
		return
	}
	var ct contact
	err := pool.QueryRow(r.Context(),
		`select name, business, customer_id from contacts where user_id = $1 and phone = $2`, uid, phone).
		Scan(&ct.Name, &ct.Business, &ct.CustomerID)
	if err != nil && !errors.Is(err, pgx.ErrNoRows) {
		serverErr(w, err)
		return
	}
	reply(w, http.StatusOK, ct) // empty fields for an unknown number
}

// saveDetails stores contact info for the number and notes/callback for the call.
// {ref} is the call id, or the Twilio CallSid the browser has right after a call.
func saveDetails(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	var in struct {
		contact
		Questions    string     `json:"questions"`
		Notes        string     `json:"notes"`
		CallbackAt   *time.Time `json:"callback_at"`
		CallbackDone bool       `json:"callback_done"`
	}
	if !decode(w, r, &in) {
		return
	}
	for _, f := range []struct {
		v   *string
		max int
	}{{&in.Name, 100}, {&in.Business, 150}, {&in.CustomerID, 64}, {&in.Questions, 5000}, {&in.Notes, 5000}} {
		*f.v = strings.TrimSpace(*f.v)
		if len(*f.v) > f.max {
			fail(w, http.StatusBadRequest, fmt.Sprintf("a field is longer than %d characters", f.max))
			return
		}
	}
	c, ok := loadCall(w, r, pool, uid, r.PathValue("ref"))
	if !ok {
		return
	}
	err := pgx.BeginFunc(r.Context(), pool, func(tx pgx.Tx) error {
		if _, err := tx.Exec(r.Context(),
			`insert into contacts (user_id, phone, name, business, customer_id) values ($1, $2, $3, $4, $5)
			 on conflict (user_id, phone) do update
			 set name = excluded.name, business = excluded.business, customer_id = excluded.customer_id, updated_at = now()`,
			uid, c.To, in.Name, in.Business, in.CustomerID); err != nil {
			return err
		}
		_, err := tx.Exec(r.Context(),
			`update calls set questions = $2, notes = $3, callback_at = $4, callback_done = $5 where id = $1`,
			c.ID, in.Questions, in.Notes, in.CallbackAt, in.CallbackDone)
		return err
	})
	if err != nil {
		serverErr(w, err)
		return
	}
	if c, ok = loadCall(w, r, pool, uid, c.ID); ok {
		reply(w, http.StatusOK, c)
	}
}

// summarize asks Gemini for a short management summary built only from what was saved.
func summarize(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	c, ok := loadCall(w, r, pool, uid, r.PathValue("id"))
	if !ok {
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), 40*time.Second)
	defer cancel()
	text, err := ai.Generate(ctx, summaryPrompt(c))
	if errors.Is(err, ai.ErrNotConfigured) {
		fail(w, http.StatusServiceUnavailable, "AI summary isn't set up on the server")
		return
	}
	if err != nil {
		log.Printf("summary: %v", err)
		fail(w, http.StatusBadGateway, "couldn't generate a summary, try again")
		return
	}
	if _, err := pool.Exec(r.Context(), `update calls set summary = $2 where id = $1`, c.ID, text); err != nil {
		serverErr(w, err)
		return
	}
	c.Summary = text
	reply(w, http.StatusOK, c)
}

func outcome(c call) string {
	if c.Status == "ended" {
		if c.DurationS > 0 {
			return "answered"
		}
		return "not answered"
	}
	return c.Status
}

func summaryPrompt(c call) string {
	or := func(s string) string {
		if s == "" {
			return "(not recorded)"
		}
		return s
	}
	callback := "none"
	if c.CallbackAt != nil {
		callback = c.CallbackAt.In(ist).Format("Mon 2 Jan 2006, 3:04 PM IST")
		if c.CallbackDone {
			callback += " (done)"
		}
	}
	return fmt.Sprintf(`You write call summaries for upper management at a small business.
Using ONLY the facts below, write a brief summary: one opening sentence (who, purpose, outcome),
then 2-4 short bullet points covering what the customer asked or needs, what was agreed, and next steps.
Do not invent details. If notes are missing, say so in one line. Plain text, "- " for bullets, under 120 words.

Date: %s
Customer: %s
Business: %s
Customer ID: %s
Phone: %s
Outcome: %s, talk time %d min %d s
Information asked during the call: %s
Key notes: %s
Callback scheduled: %s`,
		c.CreatedAt.In(ist).Format("Mon 2 Jan 2006, 3:04 PM IST"),
		or(c.Name), or(c.Business), or(c.CustomerID), c.To,
		outcome(c), c.DurationS/60, c.DurationS%60,
		or(c.Questions), or(c.Notes), callback)
}

type day struct {
	Day      string `json:"day"`
	Calls    int    `json:"calls"`
	Answered int    `json:"answered"`
	TalkS    int    `json:"talk_s"`
}

// stats feeds the dashboard: today's usage, totals, 14-day series and open callbacks.
func stats(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	ctx := r.Context()
	out := struct {
		CapS          int    `json:"cap_s"`
		TodayS        int    `json:"today_s"`
		TodayCalls    int    `json:"today_calls"`
		TodayAnswered int    `json:"today_answered"`
		TotalCalls    int    `json:"total_calls"`
		TotalS        int    `json:"total_s"`
		Daily         []day  `json:"daily"`
		Callbacks     []call `json:"callbacks"`
	}{CapS: dailyCapS}
	err := pool.QueryRow(ctx,
		`select coalesce(sum(duration_s) filter (where created_at >= `+istMidnight+`), 0),
		        count(*) filter (where created_at >= `+istMidnight+`),
		        count(*) filter (where created_at >= `+istMidnight+` and duration_s > 0),
		        count(*), coalesce(sum(duration_s), 0)
		   from calls where user_id = $1 and mode = 'twilio'`, uid).
		Scan(&out.TodayS, &out.TodayCalls, &out.TodayAnswered, &out.TotalCalls, &out.TotalS)
	if err != nil {
		serverErr(w, err)
		return
	}
	rows, err := pool.Query(ctx,
		`select to_char(d, 'YYYY-MM-DD'), count(c.id), count(c.id) filter (where c.duration_s > 0),
		        coalesce(sum(c.duration_s), 0)
		   from generate_series((now() at time zone 'Asia/Kolkata')::date - 13,
		                        (now() at time zone 'Asia/Kolkata')::date, interval '1 day') d
		   left join calls c on c.user_id = $1 and c.mode = 'twilio'
		         and (c.created_at at time zone 'Asia/Kolkata')::date = d::date
		  group by d order by d`, uid)
	if err == nil {
		out.Daily, err = pgx.CollectRows(rows, func(r pgx.CollectableRow) (day, error) {
			var d day
			return d, r.Scan(&d.Day, &d.Calls, &d.Answered, &d.TalkS)
		})
	}
	if err == nil {
		out.Callbacks, err = queryCalls(ctx, pool,
			`where c.user_id = $1 and c.callback_at is not null and not c.callback_done
			 order by c.callback_at limit 20`, uid)
	}
	if err != nil {
		serverErr(w, err)
		return
	}
	reply(w, http.StatusOK, out)
}

