import type {Call} from './api';

// Twilio errors carry code/description/explanation; plain errors carry message.
export const errMsg = (e: any): string => {
    if (typeof e === 'string') return e;
    const text = e?.message || e?.explanation || e?.description || String(e);
    return e?.code ? `${text} (Twilio ${e.code})` : text;
};

export const fmtDuration = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
export const fmtTime = (t: string) => new Date(t).toLocaleString('en-IN', {dateStyle: 'medium', timeStyle: 'short'});

// <input type="datetime-local"> speaks local time without a zone.
export const toLocalInput = (iso: string | null) => {
    if (!iso) return '';
    const d = new Date(iso);
    return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
};
export const fromLocalInput = (v: string) => (v ? new Date(v).toISOString() : null);

export type Outcome = 'answered' | 'no-answer' | 'busy' | 'canceled' | 'failed' | 'live';

export const outcomeOf = (c: Call): Outcome => {
    if (c.status === 'ended') return c.duration_s > 0 ? 'answered' : 'no-answer';
    if (c.status === 'dialing' || c.status === 'queued') return 'live';
    return (['no-answer', 'busy', 'canceled'] as const).find(s => s === c.status) ?? 'failed';
};

export const outcomes: Record<Outcome, {label: string; icon: string}> = {
    answered: {label: 'Answered', icon: '✓'},
    'no-answer': {label: 'No answer', icon: '↷'},
    busy: {label: 'Busy', icon: '⊘'},
    canceled: {label: 'Cancelled', icon: '✕'},
    failed: {label: 'Failed', icon: '!'},
    live: {label: 'In progress', icon: '●'},
};
