import {useState} from 'react';
import type {Day} from './api';
import {fmtDuration} from './util';

const W = 560, H = 180, PAD = {top: 12, right: 8, bottom: 24, left: 28};

const dayLabel = (d: string) =>
    new Date(d + 'T00:00:00').toLocaleDateString('en-IN', {day: 'numeric', month: 'short'});

// Bar chart of calls per day. Single series: the card title names it, so no legend.
export default function CallsChart({days}: {days: Day[]}) {
    const [hover, setHover] = useState<number | null>(null);
    const max = Math.max(4, ...days.map(d => d.calls));
    const top = Math.ceil(max / 2) * 2; // even, so the midline tick is a whole number
    const innerW = W - PAD.left - PAD.right, innerH = H - PAD.top - PAD.bottom;
    const slot = innerW / Math.max(days.length, 1);
    const barW = Math.min(24, slot - 6);
    const y = (v: number) => PAD.top + innerH - (v / top) * innerH;
    const h = hover === null ? null : days[hover];

    return (
        <div className="chart">
            <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Calls per day for the last 14 days"
                 onMouseLeave={() => setHover(null)}>
                {[0, top / 2, top].map(t => (
                    <g key={t}>
                        <line x1={PAD.left} x2={W - PAD.right} y1={y(t)} y2={y(t)} className="grid"/>
                        <text x={PAD.left - 6} y={y(t)} className="tick" textAnchor="end" dominantBaseline="middle">{t}</text>
                    </g>
                ))}
                {days.map((d, i) => {
                    const x = PAD.left + i * slot + (slot - barW) / 2;
                    const bh = y(0) - y(d.calls);
                    const r = Math.min(4, bh);
                    return (
                        <g key={d.day}>
                            {d.calls > 0 && (
                                <path className={`bar ${hover === i ? 'on' : ''}`}
                                      d={`M${x},${y(0)} V${y(d.calls) + r} Q${x},${y(d.calls)} ${x + r},${y(d.calls)}
                                          H${x + barW - r} Q${x + barW},${y(d.calls)} ${x + barW},${y(d.calls) + r} V${y(0)} Z`}/>
                            )}
                            {(i % 2 === days.length % 2 || i === days.length - 1) && (
                                <text x={x + barW / 2} y={H - 6} className="tick" textAnchor="middle">{dayLabel(d.day)}</text>
                            )}
                            {/* hit target is the whole column, bigger than the bar */}
                            <rect x={PAD.left + i * slot} y={PAD.top} width={slot} height={innerH} fill="transparent"
                                  onMouseEnter={() => setHover(i)} onFocus={() => setHover(i)} tabIndex={0}
                                  aria-label={`${dayLabel(d.day)}: ${d.calls} calls, ${d.answered} answered`}/>
                        </g>
                    );
                })}
            </svg>
            {h && hover !== null && (
                <div className="tip" style={{left: `${((PAD.left + (hover + 0.5) * slot) / W) * 100}%`}}>
                    <strong>{dayLabel(h.day)}</strong>
                    <span>{h.calls} calls · {h.answered} answered</span>
                    <span>Talk time {fmtDuration(h.talk_s)}</span>
                </div>
            )}
            <table className="sr-only">
                <caption>Calls per day</caption>
                <thead><tr><th>Day</th><th>Calls</th><th>Answered</th><th>Talk time</th></tr></thead>
                <tbody>{days.map(d => (
                    <tr key={d.day}><td>{dayLabel(d.day)}</td><td>{d.calls}</td><td>{d.answered}</td><td>{fmtDuration(d.talk_s)}</td></tr>
                ))}</tbody>
            </table>
        </div>
    );
}

