import {FormEvent, useEffect, useRef, useState} from 'react';
import {Call as TwilioCall, Device} from '@twilio/voice-sdk';
import {normalize, twilioToken} from './api';
import {errMsg, fmtDuration} from './util';

export type Phase = 'idle' | 'connecting' | 'ringing' | 'live';
export type LiveState = {phase: Phase; startedAt: number; to: string};

export default function Dialer({number, setNumber, live, setLive, onEnded, onError}: {
    number: string;
    setNumber: (n: string) => void;
    live: LiveState;
    setLive: (s: LiveState) => void;
    onEnded: (callSid: string | undefined) => void;
    onError: (e: unknown) => void;
}) {
    const [muted, setMuted] = useState(false);
    const [error, setError] = useState('');
    const device = useRef<Device | null>(null);
    const call = useRef<TwilioCall | null>(null);

    useEffect(() => () => device.current?.destroy(), []);

    async function getDevice() {
        if (device.current) return device.current;
        const d = new Device(await twilioToken(), {codecPreferences: [TwilioCall.Codec.Opus, TwilioCall.Codec.PCMU]});
        d.on('tokenWillExpire', () => twilioToken().then(t => d.updateToken(t)).catch(onError));
        d.on('error', e => { console.error(e); setError(errMsg(e)); });
        return (device.current = d);
    }

    async function dial(e: FormEvent) {
        e.preventDefault();
        setError('');
        let to: string;
        try {
            to = normalize(number);
        } catch (err) {
            setError(errMsg(err));
            return;
        }
        setLive({phase: 'connecting', startedAt: 0, to});
        try {
            const c = await (await getDevice()).connect({params: {To: to}});
            call.current = c;
            c.on('ringing', () => setLive({phase: 'ringing', startedAt: 0, to}));
            c.on('accept', () => setLive({phase: 'live', startedAt: Date.now(), to}));
            c.on('error', err => { console.error(err); setError(errMsg(err)); });
            let done = false;
            const end = () => {
                if (done) return;
                done = true;
                call.current = null;
                setMuted(false);
                setLive({phase: 'idle', startedAt: 0, to: ''});
                onEnded(c.parameters?.CallSid); // set once Twilio starts ringing
            };
            for (const ev of ['disconnect', 'cancel', 'reject'] as const) c.on(ev, end);
        } catch (err) {
            setLive({phase: 'idle', startedAt: 0, to: ''});
            if (err !== undefined) onError(err); // SDK rejects with nothing; the Device 'error' event already set the message
        }
    }

    function toggleMute() {
        call.current?.mute(!muted);
        setMuted(!muted);
    }

