import {useEffect, useMemo, useState} from 'react';
import {Call, Details, detailsOf, getCall, saveDetails, summarize} from './api';
import {errMsg, fmtDuration, fmtTime, fromLocalInput, Outcome, outcomeOf, outcomes, toLocalInput} from './util';

export function StatusBadge({c}: {c: Call}) {
    const o = outcomeOf(c);
    return <span className={`badge ${o}`}><i aria-hidden>{outcomes[o].icon}</i>{outcomes[o].label}</span>;
}

const who = (c: Call) => c.name || c.to;

export function DetailsForm({value, onChange, disabled}: {
    value: Details; onChange: (d: Details) => void; disabled?: boolean;
}) {
    const set = <K extends keyof Details>(k: K, v: Details[K]) => onChange({...value, [k]: v});
    return (
        <fieldset className="details" disabled={disabled}>
            <div className="row3">
                <label>Name<input value={value.name} maxLength={100} onChange={e => set('name', e.target.value)}/></label>
                <label>Business name<input value={value.business} maxLength={150} onChange={e => set('business', e.target.value)}/></label>
                <label>Customer ID<input value={value.customer_id} maxLength={64} onChange={e => set('customer_id', e.target.value)}/></label>
            </div>
            <label>Information asked during the call
                <textarea rows={3} maxLength={5000} value={value.questions} onChange={e => set('questions', e.target.value)}/>
            </label>
            <label>Key notes
                <textarea rows={3} maxLength={5000} value={value.notes} onChange={e => set('notes', e.target.value)}/>
            </label>
            <label>Callback
                <input type="datetime-local" value={toLocalInput(value.callback_at)}
                       onChange={e => onChange({...value, callback_at: fromLocalInput(e.target.value), callback_done: false})}/>
            </label>
        </fieldset>
    );
}

export function Callbacks({calls, onCall, onDone, onOpen}: {
    calls: Call[]; onCall: (c: Call) => void; onDone: (c: Call) => void; onOpen: (c: Call) => void;
}) {
    const now = Date.now();
    return (
        <section className="card">
            <h2>Callbacks due <span className="count">{calls.length}</span></h2>
            {calls.length === 0 && <p className="muted">No callbacks scheduled.</p>}
            <ul className="callbacks">
                {calls.map(c => {
                    const late = new Date(c.callback_at!).getTime() < now;
                    return (
                        <li key={c.id}>
                            <button className="plain" onClick={() => onOpen(c)}>
                                <strong>{who(c)}</strong>
                                <small>{c.business || c.to}</small>
                            </button>
                            <span className={`due ${late ? 'late' : ''}`}>
                                {late && <i aria-hidden>!</i>}{late ? 'Overdue · ' : ''}{fmtTime(c.callback_at!)}
                            </span>
                            <span className="actions">
                                <button className="primary small" onClick={() => onCall(c)}>Call</button>
                                <button className="small" onClick={() => onDone(c)}>Done</button>
                            </span>
                        </li>
                    );
                })}
            </ul>
        </section>
    );
}

const filters: Array<Outcome | 'all'> = ['all', 'answered', 'no-answer', 'busy', 'canceled', 'failed', 'live'];

export function Records({calls, more, loading, onMore, onOpen}: {
    calls: Call[]; more: boolean; loading: boolean; onMore: () => void; onOpen: (c: Call) => void;
}) {
    const [query, setQuery] = useState('');
    const [status, setStatus] = useState<Outcome | 'all'>('all');

    const shown = useMemo(() => {
        const q = query.trim().toLowerCase();
        return calls.filter(c =>
            (status === 'all' || outcomeOf(c) === status) &&
            (!q || [c.to, c.name, c.business, c.customer_id].some(f => f.toLowerCase().includes(q))));
    }, [calls, query, status]);

    function exportCsv() {
        const cell = (v: string | number | null) => `"${String(v ?? '').replace(/"/g, '""')}"`;
        const head = ['Date', 'Number', 'Name', 'Business', 'Customer ID', 'Status', 'Duration (s)',
            'Information asked', 'Key notes', 'Callback', 'Summary'];
        const rows = shown.map(c => [c.created_at, c.to, c.name, c.business, c.customer_id, outcomes[outcomeOf(c)].label,
            c.duration_s, c.questions, c.notes, c.callback_at, c.summary]);
        const blob = new Blob(['﻿' + [head, ...rows].map(r => r.map(cell).join(',')).join('\r\n')], {type: 'text/csv'});
        const a = Object.assign(document.createElement('a'), {href: URL.createObjectURL(blob), download: 'call-records.csv'});
        a.click();
        URL.revokeObjectURL(a.href);
    }

    return (
        <section className="card">
            <h2>Call records <span className="live-tag"><i aria-hidden/>Live</span></h2>
            <div className="filters">
                <input type="search" placeholder="Search name, number, business, customer ID" value={query}
                       onChange={e => setQuery(e.target.value)} aria-label="Search records"/>
                <select value={status} onChange={e => setStatus(e.target.value as Outcome | 'all')} aria-label="Status">
                    {filters.map(s => <option key={s} value={s}>{s === 'all' ? 'All statuses' : outcomes[s].label}</option>)}
                </select>
                <button onClick={exportCsv} disabled={!shown.length}>Export CSV</button>
            </div>
            {!loading && shown.length === 0 && <p className="muted">No calls{calls.length ? ' match' : ' yet'}.</p>}
            {shown.length > 0 && (
                <table className="records">
                    <thead><tr><th>Status</th><th>Contact</th><th>Business</th><th>When</th><th>Duration</th><th>Summary</th></tr></thead>
                    <tbody>
                    {shown.map(c => (
                        <tr key={c.id} onClick={() => onOpen(c)} tabIndex={0}
                            onKeyDown={e => e.key === 'Enter' && onOpen(c)}>
                            <td><StatusBadge c={c}/></td>
                            <td><strong>{who(c)}</strong>{c.name && <small>{c.to}</small>}</td>
                            <td>{c.business || '—'}{c.customer_id && <small>ID {c.customer_id}</small>}</td>
                            <td>{fmtTime(c.created_at)}</td>
                            <td>{c.duration_s > 0 ? fmtDuration(c.duration_s) : '—'}</td>
                            <td>{c.summary ? <span className="has-summary">Ready</span> : <span className="muted">—</span>}</td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            )}
            {more && <button className="more" disabled={loading} onClick={onMore}>{loading ? 'Loading…' : 'Load more'}</button>}
        </section>
    );
}

export function CallDrawer({call, onClose, onSaved, onCall, onError}: {
    call: Call; onClose: () => void; onSaved: (c: Call) => void; onCall: (c: Call) => void; onError: (e: unknown) => void;
}) {
    const [c, setC] = useState(call);
    const [draft, setDraft] = useState(detailsOf(call));
    const [busy, setBusy] = useState<'' | 'save' | 'ai'>('');
    const [msg, setMsg] = useState('');
    const dirty = JSON.stringify(draft) !== JSON.stringify(detailsOf(c));

    // Twilio's final status lands a moment after hangup; refresh once.
    useEffect(() => {
        if (outcomeOf(call) !== 'live') return;
        const t = setTimeout(() => getCall(call.id).then(n => { setC(n); onSaved(n); }).catch(() => {}), 2500);
        return () => clearTimeout(t);
    }, [call.id]);
    useEffect(() => {
        const esc = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
        addEventListener('keydown', esc);
        return () => removeEventListener('keydown', esc);
    }, []);

    async function run(kind: 'save' | 'ai') {
        setBusy(kind);
        setMsg('');
        try {
            let n = dirty || kind === 'save' ? await saveDetails(c.id, draft) : c;
            if (kind === 'ai') n = await summarize(c.id);
            setC(n);
            setDraft(detailsOf(n));
            onSaved(n);
            setMsg(kind === 'save' ? 'Saved' : '');
        } catch (e) {
            const m = errMsg(e);
            if (m === 'signed out') onError(e);
            else setMsg(m);
        } finally {
            setBusy('');
        }
    }

    async function copy() {
        try {
            await navigator.clipboard.writeText(`${who(c)}${c.business ? ` (${c.business})` : ''} · ${fmtTime(c.created_at)}\n\n${c.summary}`);
            setMsg('Summary copied');
        } catch {
            setMsg("Couldn't copy; select the text instead");
        }
    }

    const mail = `mailto:?subject=${encodeURIComponent(`Call summary: ${who(c)}`)}&body=${encodeURIComponent(c.summary)}`;
    return (
        <div className="scrim" onClick={onClose}>
            <aside className="drawer" role="dialog" aria-modal aria-label={`Call with ${who(c)}`} onClick={e => e.stopPropagation()}>
                <header>
                    <div>
                        <h2>{who(c)}</h2>
                        <p className="muted">{c.to} · {fmtTime(c.created_at)}{c.duration_s > 0 && ` · ${fmtDuration(c.duration_s)}`}</p>
                    </div>
                    <button className="plain close" onClick={onClose} aria-label="Close">✕</button>
                </header>
                <div className="drawer-meta">
                    <StatusBadge c={c}/>
                    <button className="small" onClick={() => onCall(c)}>Call again</button>
                </div>

                <DetailsForm value={draft} onChange={setDraft} disabled={!!busy}/>
                {draft.callback_at && (
                    <label className="check">
                        <input type="checkbox" checked={draft.callback_done}
                               onChange={e => setDraft({...draft, callback_done: e.target.checked})}/>
                        Callback done
                    </label>
                )}
                <div className="drawer-actions">
                    <button className="primary" disabled={!!busy || !dirty} onClick={() => run('save')}>
                        {busy === 'save' ? 'Saving…' : 'Save'}
                    </button>
                    {msg && <span className="muted" role="status">{msg}</span>}
                </div>

                <section className="summary">
                    <div className="summary-head">
                        <h3>Summary for management</h3>
                        <button className="primary small" disabled={!!busy} onClick={() => run('ai')}>
                            {busy === 'ai' ? 'Writing…' : c.summary ? 'Regenerate' : 'Generate with AI'}
                        </button>
                    </div>
                    {c.summary
                        ? <>
                            <p className="summary-text">{c.summary}</p>
                            <div className="drawer-actions">
                                <button className="small" onClick={copy}>Copy</button>
                                <a className="small button" href={mail}>Email</a>
                            </div>
                        </>
                        : <p className="muted">Save your notes, then generate a short summary you can copy or email.</p>}
                </section>
            </aside>
        </div>
    );
}

