                <button onClick={exportCsv} disabled={!shown.length}>Export CSV</button>
            </div>
            {!loading && shown.length === 0 && <p className="muted">No calls{calls.length ? ' match' : ' yet'}.</p>}
            {shown.length > 0 && (
                <table className="records">
                    <thead><tr><th>Status</th><th>Contact</th><th>Business</th><th>When</th><th>Duration</th><th>Summary</th></tr></thead>
                    <tbody>
                    {shown.map(c => (
                        <tr key={c.id} onClick={() => onOpen(c)} tabIndex={0}
                            onKeyDown={e => e.key === 'Enter' && onOpen(c)}>
                            <td><StatusBadge c={c}/></td>
                            <td><strong>{who(c)}</strong>{c.name && <small>{c.to}</small>}</td>
                            <td>{c.business || '—'}{c.customer_id && <small>ID {c.customer_id}</small>}</td>
                            <td>{fmtTime(c.created_at)}</td>
                            <td>{c.duration_s > 0 ? fmtDuration(c.duration_s) : '—'}</td>
                            <td>{c.summary ? <span className="has-summary">Ready</span> : <span className="muted">—</span>}</td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            )}
            {more && <button className="more" disabled={loading} onClick={onMore}>{loading ? 'Loading…' : 'Load more'}</button>}
        </section>
    );
}

export function CallDrawer({call, onClose, onSaved, onCall, onError}: {
    call: Call; onClose: () => void; onSaved: (c: Call) => void; onCall: (c: Call) => void; onError: (e: unknown) => void;
}) {
    const [c, setC] = useState(call);
    const [draft, setDraft] = useState(detailsOf(call));
    const [busy, setBusy] = useState<'' | 'save' | 'ai'>('');
    const [msg, setMsg] = useState('');
    const dirty = JSON.stringify(draft) !== JSON.stringify(detailsOf(c));

    // Twilio's final status lands a moment after hangup; refresh once.
    useEffect(() => {
        if (outcomeOf(call) !== 'live') return;
        const t = setTimeout(() => getCall(call.id).then(n => { setC(n); onSaved(n); }).catch(() => {}), 2500);
        return () => clearTimeout(t);
    }, [call.id]);
    useEffect(() => {
        const esc = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
        addEventListener('keydown', esc);
        return () => removeEventListener('keydown', esc);
    }, []);

    async function run(kind: 'save' | 'ai') {
        setBusy(kind);
        setMsg('');
        try {
            let n = dirty || kind === 'save' ? await saveDetails(c.id, draft) : c;
            if (kind === 'ai') n = await summarize(c.id);
            setC(n);
            setDraft(detailsOf(n));
            onSaved(n);
            setMsg(kind === 'save' ? 'Saved' : '');
        } catch (e) {
            const m = errMsg(e);
            if (m === 'signed out') onError(e);
            else setMsg(m);
        } finally {
            setBusy('');
        }
    }

    async function copy() {
        try {
            await navigator.clipboard.writeText(`${who(c)}${c.business ? ` (${c.business})` : ''} · ${fmtTime(c.created_at)}\n\n${c.summary}`);
            setMsg('Summary copied');
        } catch {
            setMsg("Couldn't copy; select the text instead");
        }
    }

    const mail = `mailto:?subject=${encodeURIComponent(`Call summary: ${who(c)}`)}&body=${encodeURIComponent(c.summary)}`;
    return (
        <div className="scrim" onClick={onClose}>
            <aside className="drawer" role="dialog" aria-modal aria-label={`Call with ${who(c)}`} onClick={e => e.stopPropagation()}>
                <header>
                    <div>
                        <h2>{who(c)}</h2>
                        <p className="muted">{c.to} · {fmtTime(c.created_at)}{c.duration_s > 0 && ` · ${fmtDuration(c.duration_s)}`}</p>
                    </div>
                    <button className="plain close" onClick={onClose} aria-label="Close">✕</button>
                </header>
                <div className="drawer-meta">
                    <StatusBadge c={c}/>
                    <button className="small" onClick={() => onCall(c)}>Call again</button>
                </div>

                <DetailsForm value={draft} onChange={setDraft} disabled={!!busy}/>
                {draft.callback_at && (
                    <label className="check">
                        <input type="checkbox" checked={draft.callback_done}
                               onChange={e => setDraft({...draft, callback_done: e.target.checked})}/>
                        Callback done
                    </label>
                )}
                <div className="drawer-actions">
                    <button className="primary" disabled={!!busy || !dirty} onClick={() => run('save')}>
                        {busy === 'save' ? 'Saving…' : 'Save'}
                    </button>
                    {msg && <span className="muted" role="status">{msg}</span>}
                </div>

                <section className="summary">
                    <div className="summary-head">
                        <h3>Summary for management</h3>
                        <button className="primary small" disabled={!!busy} onClick={() => run('ai')}>
                            {busy === 'ai' ? 'Writing…' : c.summary ? 'Regenerate' : 'Generate with AI'}
                        </button>
                    </div>
                    {c.summary
                        ? <>
                            <p className="summary-text">{c.summary}</p>
                            <div className="drawer-actions">
                                <button className="small" onClick={copy}>Copy</button>
                                <a className="small button" href={mail}>Email</a>
                            </div>
                        </>
                        : <p className="muted">Save your notes, then generate a short summary you can copy or email.</p>}
                </section>
            </aside>
        </div>
    );
}

