        connecting: 'Connecting…',
        ringing: 'Ringing…',
        live: <>On call · <Timer since={live.startedAt}/></>,
    }[live.phase];
    return <span className={`pill ${live.phase}`} role="status"><i aria-hidden/>{text}</span>;
}

function Dashboard({onSignedOut}: {onSignedOut: () => void}) {
    const [live, setLive] = useState<LiveState>({phase: 'idle', startedAt: 0, to: ''});
    const [number, setNumber] = useState('');
    const [draft, setDraft] = useState<Details>(emptyDetails);
    const draftRef = useRef(draft);
    draftRef.current = draft;
    const [st, setSt] = useState<Stats | null>(null);
    const [calls, setCalls] = useState<Call[]>([]);
    const [more, setMore] = useState(false);
    const [loading, setLoading] = useState(false);
    const [open, setOpen] = useState<Call | null>(null);
    const [notice, setNotice] = useState('');

    const onError = (e: unknown) => {
        const m = errMsg(e);
        if (m === SIGNED_OUT) onSignedOut();
        else setNotice(m);
    };

    // Live: refresh stats and the newest page; keep older pages already loaded.
    async function refresh() {
        try {
            const [s, page] = await Promise.all([fetchStats(), listCalls()]);
            setSt(s);
            setCalls(prev => {
                const oldest = page.length ? page[page.length - 1].created_at : '';
                return [...page, ...prev.filter(c => oldest && c.created_at < oldest)];
            });
            setMore(m => m || page.length === 50);
        } catch (e) {
            onError(e);
        }
    }
    useEffect(() => {
        refresh();
        const t = setInterval(() => document.visibilityState === 'visible' && refresh(), POLL_MS);
        return () => clearInterval(t);
    }, []);

    async function loadMore() {
        setLoading(true);
        try {
            const page = await listCalls(calls[calls.length - 1]?.created_at);
            setCalls(prev => [...prev, ...page]);
            setMore(page.length === 50);
        } catch (e) {
            onError(e);
        } finally {
            setLoading(false);
        }
    }

    // Prefill contact details when the number is complete.
    useEffect(() => {
        let to: string;
        try { to = normalize(number); } catch { return; }
        let stale = false;
        getContact(to).then(ct => !stale && setDraft(d => ({...d, ...ct}))).catch(() => {});
        return () => { stale = true; };
    }, [number]);

