        if (!sid) {
            setNotice("The call didn't start, so your notes are still in the form.");
            return;
        }
        try {
            const saved = await saveDetails(sid, draftRef.current);
            setDraft(d => ({...emptyDetails, name: d.name, business: d.business, customer_id: d.customer_id}));
            setNotice('');
            setOpen(saved);
        } catch (e) {
            onError(e);
        }
        setTimeout(refresh, 2000);
    }

    function callAgain(c: Call) {
        setOpen(null);
        setNumber(c.to.replace(/^\\+91/, ''));
        scrollTo({top: 0, behavior: 'smooth'});
    }

    async function markDone(c: Call) {
        try {
            await saveDetails(c.id, {...detailsOf(c), callback_done: true});
            refresh();
        } catch (e) {
            onError(e);
        }
    }

    const updated = (c: Call) => {
        setCalls(prev => prev.map(p => (p.id === c.id ? c : p)));
        setOpen(o => (o && o.id === c.id ? c : o));
        fetchStats().then(setSt).catch(() => {});
    };

    const busy = live.phase !== 'idle';
    const rate = st && st.today_calls ? Math.round((100 * st.today_answered) / st.today_calls) : 0;
    return (
        <>
            <header className="topbar">
                <div className="brand"><span className="logo" aria-hidden>☎</span>Laptop Dialer</div>
                <LivePill live={live}/>
                {st && (
                    <span className="usage" title="Daily internet calling limit">
                        Today {fmtDuration(st.today_s)} / {fmtDuration(st.cap_s)}
                        <meter min={0} max={st.cap_s} value={st.today_s}/>
                    </span>
                )}
                <button className="link" disabled={busy} onClick={onSignedOut}>Sign out</button>
            </header>
            {notice && <p className="notice" role="alert">{notice} <button className="plain" onClick={() => setNotice('')} aria-label="Dismiss">✕</button></p>}

            <div className="layout">
                <div className="side">
                    <Dialer number={number} setNumber={setNumber} live={live} setLive={setLive}
                            onEnded={callEnded} onError={onError}/>
                    <section className="card">
                        <h2>Call details</h2>
                        <p className="muted hint">Fill in during the call. Saved to the call when it ends.</p>
                        <DetailsForm value={draft} onChange={setDraft}/>
                    </section>
                </div>

                <div className="main">
                    <div className="kpis">
                        <Kpi label="Calls today" value={st?.today_calls ?? '–'}/>
                        <Kpi label="Answered today" value={st ? `${rate}%` : '–'}/>
                        <Kpi label="Talk time today" value={st ? fmtDuration(st.today_s) : '–'}/>
                        <Kpi label="Callbacks due" value={st?.callbacks.length ?? '–'}
                             alert={!!st?.callbacks.some(c => new Date(c.callback_at!).getTime() < Date.now())}/>
                    </div>
                    <section className="card">
                        <h2>Calls · last 14 days</h2>
                        {st && <CallsChart days={st.daily}/>}
                    </section>
                    <Callbacks calls={st?.callbacks ?? []} onCall={callAgain} onDone={markDone} onOpen={setOpen}/>
                    <Records calls={calls} more={more} loading={loading} onMore={loadMore} onOpen={setOpen}/>
                </div>
            </div>

            {open && <CallDrawer key={open.id} call={open} onClose={() => setOpen(null)} onSaved={updated}
                                 onCall={callAgain} onError={onError}/>}
        </>
    );
}

function Kpi({label, value, alert}: {label: string; value: string | number; alert?: boolean}) {
    return (
        <div className={`kpi ${alert ? 'alert' : ''}`}>
            <span>{label}</span>
            <strong>{value}</strong>
        </div>
    );
}
