:root {
    --bg: #eaf3ff;          /* light blue page */
    --surface: #ffffff;
    --surface-2: #f4f8fe;
    --text: #0f1f3d;
    --muted: #5b6b85;
    --border: #d5e3f6;
    --grid: #e3ecf8;
    --blue: #2563eb;        /* buttons, bars */
    --blue-hover: #1d4ed8;
    --blue-soft: #dbeafe;
    --on-blue: #ffffff;
    --good: #15803d;   --good-soft: #dcfce7;
    --warn: #b45309;   --warn-soft: #fef3c7;
    --bad: #b91c1c;    --bad-soft: #fee2e2;
    --idle: #64748b;   --idle-soft: #eef2f7;
    color-scheme: light;
}

* { box-sizing: border-box; }
body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font: 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
h1 { font-size: 22px; margin: 0 0 4px; }
h2 { font-size: 15px; margin: 0 0 12px; display: flex; align-items: center; gap: 8px; }
h3 { font-size: 14px; margin: 0; }
.muted { color: var(--muted); }
.error { color: var(--bad); margin: 0; }
.hint { margin: -6px 0 12px; font-size: 13px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* ---- controls ---- */
input, textarea, select {
    font: inherit; color: var(--text); background: var(--surface);
    border: 1px solid var(--border); border-radius: 8px; padding: 9px 11px; width: 100%;
}
textarea { resize: vertical; min-height: 64px; }
input:focus-visible, textarea:focus-visible, select:focus-visible, button:focus-visible, a:focus-visible, tr:focus-visible, rect:focus-visible {
    outline: 2px solid var(--blue); outline-offset: 2px;
}
label { display: grid; gap: 5px; font-size: 13px; color: var(--muted); }
button, .button {
    font: inherit; cursor: pointer; border-radius: 8px; padding: 8px 14px;
    border: 1px solid var(--border); background: var(--surface); color: var(--text); text-decoration: none;
    display: inline-flex; align-items: center; justify-content: center; gap: 6px;
}
button:hover:not(:disabled), .button:hover { border-color: var(--blue); }
button:disabled { opacity: .55; cursor: default; }
.primary { background: var(--blue); border-color: var(--blue); color: var(--on-blue); font-weight: 600; }
.primary:hover:not(:disabled) { background: var(--blue-hover); }
.small { padding: 5px 10px; font-size: 13px; }
.link { background: none; border: 0; color: var(--blue); padding: 4px; }
.plain { background: none; border: 0; padding: 0; color: inherit; text-align: left; }
.check { display: flex; align-items: center; gap: 8px; color: var(--text); }
.check input { width: auto; }

/* ---- sign in ---- */
main.auth { max-width: 400px; margin: 10vh auto; padding: 28px; }
main.auth form { display: grid; gap: 14px; margin-top: 20px; }

/* ---- layout ---- */
.topbar {
    position: sticky; top: 0; z-index: 5;
    display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
    padding: 12px 24px; background: var(--surface); border-bottom: 1px solid var(--border);
}
.brand { font-weight: 700; font-size: 17px; display: flex; align-items: center; gap: 8px; margin-right: auto; }
.logo {
    display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px;
    background: var(--blue); color: var(--on-blue); font-size: 16px;
}
.usage { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.usage meter { width: 90px; }
.notice {
    margin: 12px 24px 0; padding: 10px 14px; border-radius: 8px;
    background: var(--warn-soft); color: var(--warn); display: flex; justify-content: space-between; gap: 12px;
}
.layout {
    display: grid; grid-template-columns: minmax(320px, 400px) 1fr; gap: 20px;
    padding: 20px 24px 40px; max-width: 1400px; margin: 0 auto; align-items: start;
}
.side { display: grid; gap: 20px; position: sticky; top: 76px; }
.main { display: grid; gap: 20px; min-width: 0; }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 18px; }

/* ---- live status ---- */
.pill {
    display: inline-flex; align-items: center; gap: 8px; padding: 5px 12px; border-radius: 999px;
    font-size: 13px; font-weight: 600; background: var(--good-soft); color: var(--good); font-variant-numeric: tabular-nums;
}
.pill i { width: 8px; height: 8px; border-radius: 50%; background: currentColor; }
.pill.connecting, .pill.ringing { background: var(--warn-soft); color: var(--warn); }
.pill.live { background: var(--bad-soft); color: var(--bad); }
.pill:not(.idle) i, .pulse:not(.idle), .live-tag i { animation: pulse 1.2s ease-in-out infinite; }
@keyframes pulse { 50% { opacity: .3; transform: scale(.8); } }
@media (prefers-reduced-motion: reduce) { .pill i, .pulse, .live-tag i { animation: none !important; } }
.live-tag {
    display: inline-flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 600;
    color: var(--good); text-transform: uppercase; letter-spacing: .05em;
}
.live-tag i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.count { font-size: 12px; padding: 1px 8px; border-radius: 999px; background: var(--blue-soft); color: var(--blue); }

/* ---- dialer ---- */
.dialer { display: grid; gap: 12px; }
.number { display: flex; align-items: center; gap: 8px; }
.number span { font-size: 18px; color: var(--text); }
.number input { font-size: 22px; letter-spacing: .03em; }
.call { font-size: 17px; padding: 12px; }
.oncall { margin-top: 14px; padding: 14px; border-radius: 10px; background: var(--surface-2); border: 1px solid var(--border); }
.oncall-head { display: flex; align-items: center; gap: 10px; font-variant-numeric: tabular-nums; }
.oncall-head .muted { margin-left: auto; }
.pulse { width: 10px; height: 10px; border-radius: 50%; background: var(--warn); }
.pulse.live { background: var(--bad); }
.keypad { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 12px; }
.keypad button { font-size: 17px; padding: 8px; }
.controls { display: flex; gap: 8px; margin-top: 12px; }
.controls button { flex: 1; }
.controls button[aria-pressed="true"] { border-color: var(--blue); background: var(--blue-soft); }
.hangup { background: var(--bad); border-color: var(--bad); color: #fff; font-weight: 600; }
.hangup:hover:not(:disabled) { background: #991b1b; border-color: #991b1b; }

/* ---- details form ---- */
.details { border: 0; padding: 0; margin: 0; display: grid; gap: 12px; min-width: 0; }
.row3 { display: grid; grid-template-columns: 1fr; gap: 12px; }
.drawer .row3 { grid-template-columns: repeat(3, 1fr); }

/* ---- KPIs ---- */
.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.kpi { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 14px 16px; display: grid; gap: 4px; }
.kpi span { font-size: 13px; color: var(--muted); }
.kpi strong { font-size: 26px; font-variant-numeric: tabular-nums; }
.kpi.alert { border-color: var(--bad); }
.kpi.alert strong { color: var(--bad); }

/* ---- chart ---- */
.chart { position: relative; }
.chart svg { width: 100%; height: auto; display: block; overflow: visible; }
.chart .grid { stroke: var(--grid); stroke-width: 1; }
.chart .tick { fill: var(--muted); font-size: 11px; }
.chart .bar { fill: var(--blue); }
.chart .bar.on { fill: var(--blue-hover); }
.tip {
    position: absolute; top: 0; transform: translateX(-50%); pointer-events: none;
    background: var(--text); color: #fff; padding: 8px 10px; border-radius: 8px; font-size: 12px;
    display: grid; gap: 2px; white-space: nowrap; box-shadow: 0 4px 14px rgb(15 31 61 / .18);
}

/* ---- callbacks ---- */
.callbacks { list-style: none; margin: 0; padding: 0; }
.callbacks li {
    display: grid; grid-template-columns: 1fr auto auto; gap: 12px; align-items: center;
    padding: 10px 0; border-top: 1px solid var(--border);
}
.callbacks li button.plain { display: grid; cursor: pointer; }
.callbacks small, .records small { display: block; color: var(--muted); font-size: 12px; font-weight: 400; }
.due { font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.due.late { color: var(--bad); font-weight: 600; }
.due i { font-style: normal; margin-right: 4px; }
.actions { display: flex; gap: 6px; }

/* ---- records ---- */
.filters { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.filters input { flex: 1; min-width: 200px; width: auto; }
.filters select { width: auto; }
.records { width: 100%; border-collapse: collapse; font-size: 14px; }
.records th { text-align: left; font-size: 12px; color: var(--muted); font-weight: 500; padding: 6px 8px; }
.records td { padding: 10px 8px; border-top: 1px solid var(--border); font-variant-numeric: tabular-nums; vertical-align: top; }
.records tbody tr { cursor: pointer; }
.records tbody tr:hover { background: var(--surface-2); }
.has-summary { color: var(--blue); font-weight: 600; font-size: 13px; }
.more { margin-top: 12px; width: 100%; }

.badge {
    display: inline-flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 600;
    padding: 2px 9px 2px 3px; border-radius: 999px; white-space: nowrap;
    background: var(--idle-soft); color: var(--idle);
}
.badge i {
    font-style: normal; display: grid; place-items: center; width: 17px; height: 17px;
    border-radius: 50%; background: currentColor; font-size: 10px;
}
.badge i::first-line { color: #fff; }
.badge i { color: inherit; }
.badge.answered { background: var(--good-soft); color: var(--good); }
.badge.no-answer, .badge.busy { background: var(--warn-soft); color: var(--warn); }
.badge.failed { background: var(--bad-soft); color: var(--bad); }
.badge.live { background: var(--blue-soft); color: var(--blue); }

/* ---- drawer ---- */
.scrim { position: fixed; inset: 0; background: rgb(15 31 61 / .35); z-index: 10; display: flex; justify-content: flex-end; }
.drawer {
    width: min(620px, 100%); height: 100%; overflow-y: auto; background: var(--surface);
    padding: 22px; display: grid; gap: 16px; align-content: start; box-shadow: -8px 0 30px rgb(15 31 61 / .15);
}
.drawer header { display: flex; justify-content: space-between; gap: 12px; }
.drawer header h2 { font-size: 20px; margin: 0; }
.drawer header p { margin: 2px 0 0; font-size: 13px; }
.close { font-size: 18px; color: var(--muted); cursor: pointer; padding: 4px; }
.drawer-meta, .drawer-actions { display: flex; align-items: center; gap: 10px; }
.summary { background: var(--surface-2); border: 1px solid var(--border); border-radius: 10px; padding: 14px; display: grid; gap: 10px; }
.summary-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.summary-text { margin: 0; white-space: pre-wrap; }

/* ---- responsive ---- */
@media (max-width: 1100px) { .kpis { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 860px) {
    .layout { grid-template-columns: 1fr; padding: 16px; }
    .side { position: static; }
    .topbar { padding: 10px 16px; }
    .usage meter { display: none; }
}
@media (max-width: 600px) {
    .drawer .row3 { grid-template-columns: 1fr; }
    .records thead { display: none; }
    .records tr { display: grid; grid-template-columns: 1fr auto; padding: 8px 0; border-top: 1px solid var(--border); }
    .records td { border: 0; padding: 2px 4px; }
    .records td:nth-child(3), .records td:nth-child(6) { display: none; }
    .callbacks li { grid-template-columns: 1fr; gap: 6px; }
}

