main { max-width: 420px; margin: 0 auto; padding: 24px 20px; }
header { display: flex; align-items: center; justify-content: space-between; }
h1 { font-size: 20px; margin: 0 0 4px; }
h2 { font-size: 13px; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin: 28px 0 8px; }
.muted { color: var(--muted); }
.error { color: var(--error); margin: 0; }

form { display: grid; gap: 14px; margin-top: 20px; }
label { display: grid; gap: 6px; font-size: 13px; color: var(--muted); }

input {
    font: inherit;
    color: var(--text);
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 10px 12px;
    width: 100%;
}
input:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.number { display: flex; align-items: center; gap: 8px; }
.number span { font-size: 18px; color: var(--text); }
.number input { font-size: 22px; letter-spacing: .03em; }

button { font: inherit; cursor: pointer; }
button:disabled { opacity: .6; cursor: default; }
.primary {
    background: var(--accent);
    color: var(--accent-text);
    border: 0;
    border-radius: 8px;
    padding: 12px;
    font-weight: 600;
}
.call { font-size: 17px; padding: 14px; }
.link { background: none; border: 0; color: var(--accent); padding: 4px; }

.status {
    margin-top: 16px;
    padding: 14px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--surface);
    display: grid;
    gap: 4px;
}
.status.live { background: var(--live); }

.history { list-style: none; margin: 0; padding: 0; }
.row {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: none;
    border: 0;
    border-bottom: 1px solid var(--border);
    color: var(--text);
    padding: 10px 2px;
    text-align: left;
}
.row small { display: block; color: var(--muted); font-size: 12px; }

.controls { display: flex; gap: 8px; margin-top: 8px; }
.controls button {
    flex: 1;
    padding: 10px;
    border-radius: 8px;
    border: 1px solid var(--border);
    background: var(--surface);
    color: var(--text);
}
.controls button[aria-pressed="true"] { border-color: var(--accent); }
.controls .hangup { background: var(--error); border-color: var(--error); color: #fff; font-weight: 600; }

main.wide { max-width: 760px; }
.usage { display: flex; align-items: center; gap: 10px; margin: 8px 0 0; font-size: 13px; }
.usage meter { flex: 1; max-width: 200px; }

.tabs { display: flex; gap: 4px; margin-top: 18px; border-bottom: 1px solid var(--border); }
.tabs button {
    background: none; border: 0; border-bottom: 2px solid transparent;
    color: var(--muted); padding: 8px 12px; margin-bottom: -1px;
}
.tabs button[aria-selected="true"] { color: var(--text); border-bottom-color: var(--accent); font-weight: 600; }
.dialer { max-width: 420px; }
.status { max-width: 420px; }

.keypad { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 8px; }
.keypad button, .filters button, .more, select {
    font: inherit; padding: 8px; border-radius: 8px;
    border: 1px solid var(--border); background: var(--surface); color: var(--text);
}

.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 18px 0 12px; }
.stats div {
    display: grid; padding: 12px; border: 1px solid var(--border);
    border-radius: 8px; background: var(--surface);
}
.stats strong { font-size: 20px; font-variant-numeric: tabular-nums; }
.stats span { font-size: 12px; color: var(--muted); }

.filters { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.filters input { flex: 1; min-width: 160px; width: auto; }

.records { width: 100%; border-collapse: collapse; font-size: 14px; }
.records th { text-align: left; font-size: 12px; color: var(--muted); font-weight: 500; padding: 6px 8px; }
.records td { padding: 10px 8px; border-top: 1px solid var(--border); font-variant-numeric: tabular-nums; }
.badge { font-size: 12px; padding: 2px 8px; border-radius: 999px; background: var(--border); }
.badge.ok { background: var(--live); color: var(--accent); }
.more { margin-top: 12px; width: 100%; }

@media (max-width: 560px) {
    .records thead { display: none; }
    .records tr { display: grid; grid-template-columns: 1fr auto; padding: 8px 0; border-top: 1px solid var(--border); }
    .records td { border: 0; padding: 2px 4px; }
    .records td:first-child { grid-column: 1 / -1; font-size: 12px; color: var(--muted); }
}

