// Usage: node shot.mjs <port> <url> <token> <out-prefix>
const [port, url, token, out] = process.argv.slice(2);
const fs = await import('node:fs');
const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const ws = new WebSocket(list.find(t => t.type === 'page').webSocketDebuggerUrl);
let id = 0; const pending = new Map();
ws.onmessage = e => { const m = JSON.parse(e.data); pending.get(m.id)?.(m); };
await new Promise(r => ws.onopen = r);
const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({id: i, method, params})); });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const shot = async (name, w, h) => {
  await send('Emulation.setDeviceMetricsOverride', {width: w, height: h, deviceScaleFactor: 1, mobile: w < 600});
  await sleep(800);
  const {result} = await send('Page.captureScreenshot', {format: 'png', captureBeyondViewport: true});
  fs.writeFileSync(`${out}-${name}.png`, Buffer.from(result.data, 'base64'));
};
await send('Page.enable'); await send('Runtime.enable');
await send('Page.navigate', {url}); await sleep(1500);
await send('Runtime.evaluate', {expression: `localStorage.setItem('ld_token', ${JSON.stringify(token)})`});
await send('Page.reload'); await sleep(3000);
const errs = await send('Runtime.evaluate', {expression: 'document.body.innerText.slice(0,300)', returnByValue: true});
console.log(errs.result.result.value);
await shot('desktop', 1440, 1000);
await shot('mobile', 390, 900);
// open the first record's drawer
await send('Emulation.setDeviceMetricsOverride', {width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false});
await send('Runtime.evaluate', {expression: `document.querySelector('.records tbody tr')?.click()`}); await sleep(800);
const {result} = await send('Page.captureScreenshot', {format: 'png'});
fs.writeFileSync(`${out}-drawer.png`, Buffer.from(result.data, 'base64'));
ws.close();
EOF
