attachment.snippet:
1	import {useEffect, useRef, useState} from 'react';
2	import type {Day} from './api';
3	import {fmtDuration} from './util';
4	
5	const H = 200, PAD = {top: 12, right: 8, bottom: 26, left: 28};
6	
7	const dayLabel = (d: string) =>
8	    new Date(d + 'T00:00:00').toLocaleDateString('en-IN', {day: 'numeric', month: 'short'});
9	
10	// Bar chart of calls per day. Single series: the card title names it, so no legend.
11	export default function CallsChart({days}: {days: Day[]}) {
12	    const [hover, setHover] = useState<number | null>(null);
