package server

import (
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"strconv"
	"time"

	"github.com/jackc/pgx/v5"

	"paytmcall/pkg/auth"
	"paytmcall/pkg/db"
	"paytmcall/pkg/telephony"
)

const (
	recordingLinkTTL = 6 * time.Hour
	// Vercel caps a response at 4.5 MB, so audio goes out in ranges of at most this size.
	recordingChunk = 2 << 20
)

var (
	recSidRe = regexp.MustCompile(`^RE[0-9a-f]{32}$`)
	rangeRe  = regexp.MustCompile(`^bytes=(\d+)-(\d*)$`)
	twilio   = &http.Client{Timeout: 25 * time.Second}
)

// recordingURL is a signed, expiring playback link: <audio> can't send the JWT header.
func recordingURL(callID string) string {
	exp := strconv.FormatInt(time.Now().Add(recordingLinkTTL).Unix(), 10)
	sig, err := auth.Sign(callID + "." + exp)
	if err != nil {
		return ""
	}
	return "/api/recordings/" + callID + "?" + url.Values{"exp": {exp}, "sig": {sig}}.Encode()
}

// twilioRecording is Twilio's recordingStatusCallback for <Dial record>; CallSid is the browser leg.
func twilioRecording(w http.ResponseWriter, r *http.Request) {
	form, err := telephony.ParseWebhook(w, r)
	if err != nil {
		log.Printf("recording webhook: %v", err)
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	sid := form.Get("RecordingSid")
	if form.Get("RecordingStatus") != "completed" || !recSidRe.MatchString(sid) {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	secs, _ := strconv.Atoi(form.Get("RecordingDuration"))
	pool, err := db.Pool()
	if err == nil {
		var tag interface{ RowsAffected() int64 }
		tag, err = pool.Exec(r.Context(),
			`update calls set recording_sid = $2, recording_s = $3 where call_sid = $1 and mode = 'twilio'`,
			form.Get("CallSid"), sid, max(secs, 0))
		if err == nil && tag.RowsAffected() == 0 {
			log.Printf("recording %s: no call %s", sid, form.Get("CallSid"))
		}
	}
	if err != nil {
		log.Printf("recording update: %v", err)
	}
	w.WriteHeader(http.StatusNoContent)
}

// twilioWhisper plays to the callee on answer, before the call connects.
func twilioWhisper(w http.ResponseWriter, r *http.Request) {
	if _, err := telephony.ParseWebhook(w, r); err != nil {
		log.Printf("whisper webhook: %v", err)
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	twiml(w, "<Say>This call may be recorded.</Say>")
}

// streamRecording proxies the MP3 from Twilio in byte ranges so <audio> can play and seek.
func streamRecording(w http.ResponseWriter, r *http.Request) {
	id, q := r.PathValue("id"), r.URL.Query()
	exp, _ := strconv.ParseInt(q.Get("exp"), 10, 64)
	if !uuidRe.MatchString(id) || time.Now().Unix() > exp || !auth.Verify(id+"."+q.Get("exp"), q.Get("sig")) {
		http.Error(w, "link expired, reopen the call", http.StatusForbidden)
		return
	}
	start, end, ok := parseRange(r.Header.Get("Range"))
	if !ok {
		http.Error(w, "bad range", http.StatusRequestedRangeNotSatisfiable)
		return
	}
	pool, err := db.Pool()
	if err != nil {
		serverErr(w, err)
		return
	}
	var rec *string
	err = pool.QueryRow(r.Context(), `select recording_sid from calls where id = $1`, id).Scan(&rec)
	if errors.Is(err, pgx.ErrNoRows) || (err == nil && rec == nil) {
		http.Error(w, "no recording", http.StatusNotFound)
		return
	}
	if err != nil {
		serverErr(w, err)
		return
	}
	req, err := http.NewRequestWithContext(r.Context(), http.MethodGet,
		fmt.Sprintf("https://api.twilio.com/2010-04-01/Accounts/%s/Recordings/%s.mp3", telephony.AccountSID(), *rec), nil)
	if err != nil {
		serverErr(w, err)
		return
	}
	req.SetBasicAuth(os.Getenv("TWILIO_API_KEY"), os.Getenv("TWILIO_API_SECRET"))
	req.Header.Set("Range", fmt.Sprintf("bytes=%d-%d", start, end))
	resp, err := twilio.Do(req)
	if err != nil {
		log.Printf("recording fetch: %v", err)
		http.Error(w, "couldn't load recording", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusPartialContent {
		log.Printf("recording fetch: twilio %d", resp.StatusCode)
		http.Error(w, "couldn't load recording", http.StatusBadGateway)
		return
	}
	for _, h := range []string{"Content-Range", "Content-Length"} {
		if v := resp.Header.Get(h); v != "" {
			w.Header().Set(h, v)
		}
	}
	w.Header().Set("Content-Type", "audio/mpeg")
	w.Header().Set("Accept-Ranges", "bytes")
	w.Header().Set("Cache-Control", "private, max-age=3600")
	w.WriteHeader(resp.StatusCode)
	// ponytail: if Twilio ever ignores Range (200), files over ~4.5 MB will fail on Vercel.
	io.Copy(w, resp.Body)
}

// parseRange turns "bytes=a-b" (or none) into a range no longer than recordingChunk.
// A shorter 206 than asked for is valid; players request the rest.
func parseRange(h string) (start, end int64, ok bool) {
	if h == "" {
		return 0, recordingChunk - 1, true
	}
	m := rangeRe.FindStringSubmatch(h)
	if m == nil {
		return 0, 0, false
	}
	start, _ = strconv.ParseInt(m[1], 10, 64)
	end = start + recordingChunk - 1
	if m[2] != "" {
		e, _ := strconv.ParseInt(m[2], 10, 64)
		if e < start {
			return 0, 0, false
		}
		end = min(e, end)
	}
	return start, end, true
}

