sed -i '' 's#for _, path := range \[\]string{"/api/voice", "/api/status"}#for _, path := range []string{"/api/voice", "/api/status", "/api/recording", "/api/whisper"}#' pkg/server/server_test.go && cat >> pkg/server/server_test.go <<'EOF'

func TestParseRange(t *testing.T) {
	const c = recordingChunk
	for h, want := range map[string][3]int64{ // start, end, ok(1/0)
		"":              {0, c - 1, 1},
		"bytes=0-":      {0, c - 1, 1},
		"bytes=100-199": {100, 199, 1},
		"bytes=10-":     {10, 10 + c - 1, 1},
		"bytes=0-99999999": {0, c - 1, 1}, // capped to one chunk
		"bytes=5-2":     {0, 0, 0},
		"bytes=-500":    {0, 0, 0}, // suffix ranges unsupported
		"items=0-1":     {0, 0, 0},
	} {
		s, e, ok := parseRange(h)
		if got := [3]int64{s, e, map[bool]int64{true: 1}[ok]}; got != want {
			t.Errorf("%q: got %v want %v", h, got, want)
		}
	}
}

func TestRecordingLinks(t *testing.T) {
	t.Setenv("JWT_SECRET", strings.Repeat("k", 32))
	id := "11111111-2222-3333-4444-555555555555"
	link := recordingURL(id)
	if !strings.HasPrefix(link, "/api/recordings/"+id+"?") {
		t.Fatalf("link %q", link)
	}
	h := New()
	for name, target := range map[string]string{
		"tampered sig": link[:len(link)-2] + "xx",
		"other call":   strings.Replace(link, id, "99999999-2222-3333-4444-555555555555", 1),
		"expired":      "/api/recordings/" + id + "?exp=1&sig=x",
		"missing":      "/api/recordings/" + id,
	} {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest("GET", target, nil))
		if rec.Code != http.StatusForbidden {
			t.Errorf("%s: got %d", name, rec.Code)
		}
	}
}
EOF
