// Hangup ends a live call; ending one that already finished is not an error.
func Hangup(ctx context.Context, callSid string) error {
	form := url.Values{"Status": {"completed"}}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost,
		"https://api.twilio.com/2010-04-01/Accounts/"+AccountSID()+"/Calls/"+callSid+".json",
		strings.NewReader(form.Encode()))
	if err != nil {
		return err
	}
	req.SetBasicAuth(os.Getenv("TWILIO_API_KEY"), os.Getenv("TWILIO_API_SECRET"))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
